// Üretilen dosya: tool/ozgun/uret.py. Edebiyat · Rus, Fransız ve İngiliz edebiyatı klasikleri (zor).
const ozLiterature10Zor = <(String, String, List<String>, String)>[
  ('Puşkin\'in \'Bronz Süvari\' adlı manzum anlatısında yoksul memur Yevgeni\'nin aklını yitirmesine yol açan felaket nedir?', '1824\'te Petersburg\'u basan büyük sel', ['Napolyon ordusunun Moskova\'yı yakması', 'Kırım\'da patlak veren veba salgını', 'Kışlık sarayda çıkan büyük yangın'], 'Bronz Süvari\'de Neva\'nın taşması sonucu nişanlısını yitiren Yevgeni, Büyük Petro\'nun atlı heykelinin kendisini kovaladığını sanır.'),
  ('Puşkin\'in \'Belkin Öyküleri\' kitabının kurgusal özelliği nedir?', 'Beş öykünün, ölmüş bir taşra toprak sahibine ait olduğu söylenerek sunulması', ['Öykülerin tümünün Kafkasya\'daki bir kalede geçmesi', 'Her öykünün farklı bir Avrupa dilinden yapılmış eski bir çeviri gibi sunulması', 'Öykülerin bir yolculuk boyunca anlatılan masallar olması'], 'Puşkin bu beş öyküyü kurgusal yazar İvan Petroviç Belkin\'in mirası gibi yayımcı ağzından sunmuştur.'),
  ('Yevgeni Onegin\'in yazıldığı ve 14 dizeden oluşan özel kıta biçimine ne ad verilir?', 'Onegin kıtası', ['Sicilya oktavı', 'Spenser kıtası', 'Petrarka sonesi'], 'Puşkin romanı, belirli bir uyak düzenine sahip 14 dizelik kendine özgü kıtalarla yazmıştır; bu kıtaya Onegin kıtası denir.'),
  ('Puşkin\'in \'Çingeneler\' poemasında çingenelerin arasına katılan Aleko\'nun sonunda topluluktan kovulmasının nedeni nedir?', 'Kendisini terk eden Zemfira\'yı ve sevgilisini kıskançlıkla öldürmesi', ['Çingenelerin atlarını çalıp kente kaçması', 'Topluluğun yaşlı önderini çar askerlerine ihbar ederek tutuklatması', 'Çingenelerin dilini ve geleneklerini küçümseyen şiirler yazması'], 'Uygarlıktan kaçıp özgürlük arayan Aleko, kendi bencil tutkusundan kurtulamaz; yaşlı çingene ona \'yalnız kendin için özgürlük istiyorsun\' diyerek onu topluluktan uzaklaştırır.'),
  ('Puşkin\'in büyük dedesi Abram Gannibal\'ın yaşamından esinlenen yarım kalmış romanının adı nedir?', 'Büyük Petro\'nun Zencisi', ['Bir Şairin Soyu', 'Petersburg\'da Bir Yabancı', 'Afrikalı Prens'], 'Puşkin\'in anne tarafından büyük dedesi Afrika kökenli Abram Gannibal, Büyük Petro\'nun himayesinde yetişmiştir; Puşkin bu öyküyü bitirmediği bir romana dönüştürmeye başlamıştır.'),
  ('Puşkin\'in Kırım Hanı Giray\'ın sarayındaki bir aşk öyküsünü işleyen romantik manzum öyküsü hangisidir?', 'Bahçesaray Çeşmesi', ['Ruslan ile Ludmila\'nın Masalı', 'Kont Nulin', 'Kolomna\'daki Ev'], 'Bahçesaray Çeşmesi (1823), Puşkin\'in güney sürgünü döneminde yazdığı ve Byron etkisi taşıyan romantik poemalarındandır.'),
  ('Zamanımızın Bir Kahramanı\'nın \'Prenses Meri\' bölümünde Peçorin\'in düelloda öldürdüğü kişi kimdir?', 'Gruşnitski', ['Maksim Maksimiç', 'Vuliç', 'Kazbiç'], 'Peçorin, kendisini kıskanan ve küçük düşürmeye çalışan Gruşnitski ile Pyatigorsk yakınlarında düello eder ve onu öldürür.'),
  ('Lermontov\'un \'Mtsıri\' poemasında manastırdan kaçan genç rahip adayının yaşadığı en çarpıcı olay hangisidir?', 'Ormanda bir parsla boğuşup onu öldürmesi', ['Bir dağ köyünde hanın kızıyla evlenip orada kalması', 'Çar ordusuna katılıp madalya kazanması', 'Denize açılıp bir fırtınada kaybolması'], 'Mtsıri, özgürlüğe kavuştuğu üç günde bir parsla dövüşür ve yaralanır; sonunda manastıra geri getirilip ölür.'),
  ('Müfettiş\'in son sahnesinde gerçek müfettişin geldiği haber verildiğinde kişilerin donup kalmasına ne ad verilir ve bu sahne neyi vurgular?', 'Sessiz sahne; yolsuzluğun açığa çıkışı karşısındaki dehşeti', ['Koro sahnesi; halkın yöneticilerine duyduğu derin sevgi ve bağlılığı', 'Epilog; yazarın seyirciden af dilemesini', 'Bale sahnesi; kasabanın kutlama coşkusunu'], 'Gogol, oyunu kişilerin heykel gibi donduğu bir \'sessiz sahne\' ile bitirir; bu sahne cezalandırılma korkusunu ve ahlaki yargıyı simgeler.'),
  ('Gogol\'ün \'Ölü Canlar\'ı düzyazı olmasına karşın hangi tür adıyla nitelemesi dikkat çekicidir?', 'Poema', ['Vodvil', 'Kronik', 'Elegi'], 'Gogol, Ölü Canlar\'ın kapağına \'poema\' yazdırmış; böylece eserini Dante\'ninki gibi destansı bir bütünün parçası olarak düşündüğünü göstermiştir.'),
  ('Gogol\'ün kararsız bir bekârın, nişanlandığı gün pencereden atlayıp kaçmasıyla biten komedyası hangisidir?', 'Evlenme', ['Kumarbazlar', 'Müfettiş', 'Yeni Bir Komedinin Gösteriminden Sonra'], '\'Evlenme\' oyununda Podkolyosin, çöpçatanlar aracılığıyla nişanlansa da son anda pencereden atlayarak kaçar.'),
  ('Akıllılık Belası\'nın yazarı Griboyedov\'un yaşamının sonu nasıl olmuştur?', 'Elçi olarak bulunduğu Tahran\'da elçiliğe yapılan saldırıda öldürülmüştür', ['Kafkasya\'daki bir düelloda bir subay tarafından vurularak ölmüştür', 'Sibirya sürgününde veremden ölmüştür', 'Paris\'te sürgündeyken intihar etmiştir'], 'Diplomat olan Griboyedov, 1829\'da Tahran\'daki Rus elçiliğine öfkeli bir kalabalığın saldırısında hayatını kaybetmiştir.'),
  ('Radişçev\'in 1790\'da yayımladığı \'Petersburg\'dan Moskova\'ya Yolculuk\' kitabı yazarına ne kazandırmıştır?', 'Serfliği eleştirdiği için Sibirya\'ya sürgün edilmesine yol açmıştır', ['Çariçe tarafından saray tarihçiliğine atanmasını sağlamıştır', 'Rusya\'da verilen ilk büyük edebiyat ödülünü almasını sağlamıştır', 'Fransız Akademisi\'ne üye seçilmesine neden olmuştur'], 'Yolculuk notları biçimindeki kitapta köylülerin acıları ve serflik sert biçimde eleştirildiği için II. Katerina, Radişçev\'i önce ölüme, sonra Sibirya sürgününe mahkûm ettirmiştir.'),
  ('Turgenyev\'in \'Arifesinde\' romanında Yelena\'nın her şeyi bırakıp evlendiği İnsarov kimdir?', 'Ülkesinin Osmanlı yönetiminden kurtuluşu için çalışan Bulgar bir devrimci', ['Yurt dışından dönen, varlıklı ve tembel bir Rus ressam', 'Kafkasya\'dan gelen Çerkes bir prens', 'Fransız bir bilim insanı ve hekim'], 'Turgenyev \'Arifesinde\'de (1860) eylem insanı tipini bir yabancıda, Bulgar İnsarov\'da arar; Yelena onunla birlikte Balkanlara gitmek üzere yola çıkar.'),
  ('Turgenyev\'in Baden-Baden\'deki Rus göçmenleri hicvettiği romanı hangisidir?', 'Duman', ['Bakir Topraklar', 'Soylular Yuvası', 'Kaynak Suları'], '\'Duman\' (1867), Avrupa\'daki Rus aydınlarının boş tartışmalarını ve Litvinov\'un yıkıcı aşkını anlatır.'),
  ('Turgenyev\'in \'Soylular Yuvası\' romanında Liza Kalitina\'nın sonunda verdiği karar nedir?', 'Manastıra kapanmak', ['Lavretski ile yurt dışına kaçmak', 'Zengin bir subayla evlenmek', 'Köy okulunda öğretmenlik yapmak'], 'Lavretski\'nin öldüğü sanılan karısı geri dönünce Liza, aşkından vazgeçerek manastıra girer.'),
  ('Turgenyev\'in, kahramanlarından çok atmosfer ve duygu gerilimine dayanan, bu yüzden Çehov\'un oyunlarının habercisi sayılan oyunu hangisidir?', 'Köyde Bir Ay', ['Akıllılık Belası', 'Vanya Dayı', 'Fırtına'], '\'Köyde Bir Ay\', bir malikânedeki gizli aşkları ve sessiz gerilimleri işler; bu yönüyle Çehov tiyatrosunu önceden haber verir.'),
  ('Oblomov romanında yer alan \'Oblomov\'un Düşü\' bölümünün işlevi nedir?', 'Kahramanın tembelliğinin kökenini çocukluğundaki uyuşuk malikâne yaşamında göstermek', ['Kahramanın gelecekteki ölümünü önceden bildirmek', 'Rus çarlığının tarihini özetlemek', 'Stolz\'un Almanya\'daki gençliğini ve aldığı eğitimi ayrıntılı biçimde anlatmak'], 'Bu bölümde Oblomovka malikânesindeki uykulu, değişmeyen yaşam anlatılır; kahramanın eylemsizliği bu ortamla açıklanır.'),
  ('\'Oblomovluk Nedir?\' başlıklı ünlü eleştiri yazısıyla Gonçarov\'un kahramanını bir toplumsal tipe dönüştüren eleştirmen kimdir?', 'Nikolay Dobrolyubov', ['Vissarion Belinski', 'Dmitri Pisarev', 'Nikolay Gavriloviç Çernışevski'], 'Dobrolyubov 1859\'da yazdığı yazıda Oblomov\'u Onegin, Peçorin ve Rudin\'le aynı soydan, eylemsiz soylu aydın tipi olarak yorumlamıştır.'),
  ('Oblomov romanının sonunda kahramanın yaşamı nasıl sonuçlanır?', 'Ev sahibesi dul Agafya Pşenitsına ile evlenip sakin bir yaşamın içinde ölür', ['Stolz ile birlikte yurt dışına gidip orada büyük bir ticaret şirketi kurar', 'Malikânesine dönüp köylülerini özgür bırakır', 'Olga ile evlenip Petersburg\'a yerleşir'], 'Oblomov, Vıborg yakasındaki evinde Agafya\'nın şefkatli bakımı altında hareketsiz bir yaşam sürer ve felç sonucu ölür.'),
  ('Gogol\'ün \'Seçme Mektuplar\'ına tepki olarak yazdığı açık mektubu bir toplantıda okumak, Dostoyevski\'nin 1849\'da tutuklanma gerekçeleri arasında yer almıştır. Bu mektubun yazarı olan eleştirmen kimdir?', 'Vissarion Belinski', ['Nikolay Dobrolyubov', 'Aleksandr Gertsen', 'Dmitri Pisarev'], 'Belinski\'nin 1847 tarihli \'Gogol\'e Mektup\'u, Petraşevski çevresinde okunmuş; Dostoyevski bu metni okuduğu için yargılananlar arasında yer almıştır.'),
  ('Babalar ve Oğullar\'da Bazarov\'un arkadaşı Arkadi\'nin romanın sonunda nasıl bir yol tuttuğu, yazarın kuşak çatışmasına bakışını nasıl yansıtır?', 'Arkadi nihilizmi bırakıp evlenir ve babasının düzenine uyar; radikallik geçici bir heves gibi görünür', ['Arkadi Bazarov\'dan daha radikal bir devrimciye dönüşür; yeni kuşak kesin zafer kazanır', 'Arkadi kenti bırakıp manastıra girer; dinin tek çıkış yolu olduğu vurgulanır', 'Arkadi babasıyla bağlarını koparır; iki kuşağın uzlaşmasının imkânsızlığı vurgulanır'], 'Arkadi, Katya ile evlenip çiftlik yönetimine yönelir; Turgenyev böylece Bazarov\'un yalnızlığını ve \'babalar\'la \'oğullar\' arasındaki uzlaşma olasılığını birlikte gösterir.'),
  ('Suç ve Ceza\'da Dunya\'nın peşine düşen ve sonunda kendini vuran ahlaksız toprak sahibi hangi işlevi üstlenir?', 'Raskolnikov\'un kuramını sonuna dek yaşayan karanlık bir ikiz olarak onun olası geleceğini göstermek', ['Romanın asıl katilinin aslında kendisi olduğunu okura sezdirmek', 'Sonya\'yı kurtaran iyi kalpli bir koruyucu olmak', 'Polisin Raskolnikov\'u yakalamasını sağlayan tanık olmak'], 'Svidrigaylov, vicdan duymadan sınırları aşan bir adamdır; onun intiharı, Raskolnikov\'un kuramının vardığı çıkmazı gösterir.'),
  ('Karamazov Kardeşler\'de Alyoşa\'nın manastırdaki ruhani öğretmeni olan ve ölümünden sonra bedeninin çabuk kokuşması kasabada skandal yaratan kişi kimdir?', 'Zosima', ['Ferapont', 'Paisiy', 'Rakitin'], 'Halk, ermiş sayılan Zosima\'nın bedeninin bozulmayacağını bekler; bedenin kokması Alyoşa\'nın inancını sarsar.'),
  ('Karamazov Kardeşler\'de İvan\'ın \'Tanrı yoksa her şey mubahtır\' düşüncesinin romandaki trajik sonucu nedir?', 'Smerdyakov\'un bu düşünceden cesaret alarak cinayeti işlediğini söylemesi', ['İvan\'ın bu düşünceyi bir dergide yazdığı için sürgüne gönderilmesi', 'Alyoşa\'nın manastırdan ayrılıp devrimci olması', 'Dmitri\'nin bu sözü duyunca babasını bağışlaması'], 'Smerdyakov, İvan\'ın kuramını uygulamaya koyduğunu ve onun sessiz onayıyla öldürdüğünü söyler; bu, İvan\'ın vicdanını parçalar.'),
  ('Dostoyevski\'nin \'Ecinniler\' romanı hangi gerçek olaydan esinlenmiştir?', 'Neçayev\'in kurduğu devrimci örgütün bir öğrenciyi öldürmesinden', ['Çar II. Aleksandr\'a düzenlenen ve başarıyla sonuçlanan bombalı suikasttan', 'Dekabrist ayaklanmasından', 'Kırım Savaşı\'ndaki Sivastopol kuşatmasından'], '1869\'da Sergey Neçayev\'in örgütü, ayrılmak isteyen öğrenci İvanov\'u öldürmüştür; Dostoyevski bu olaydan yola çıkarak radikal devrimciliği eleştirir.'),
  ('Ecinniler\'de her şeye kayıtsız, çekici ama içten içe boşlukla kemirilen ve sonunda kendini asan aristokrat kimdir?', 'Nikolay Stavrogin', ['Pyotr Stepanoviç Verhovenski', 'İvan Şatov', 'Aleksey Kirillov'], 'Herkesin etrafında döndüğü Stavrogin, inançsızlığın yarattığı ruhsal boşluğun simgesidir; Pyotr Verhovenski ise örgütün entrikacı önderidir.'),
  ('Dostoyevski\'nin ağabeyi Mihail ile birlikte çıkardığı dergiler hangileridir?', 'Vremya ve Epoha', ['Sovremennik ve Otecestvennıye Zapiski', 'Kolokol ve Polyarnaya Zvezda', 'Russkiy Vestnik ve Moskvityanin'], 'Sürgünden dönen Dostoyevski, Mihail ile \'Vremya\' (Zaman) ve ardından \'Epoha\' (Çağ) dergilerini çıkarmıştır; ikisi de kapanmış ve borç bırakmıştır.'),
  ('Dostoyevski\'nin 1880\'de Moskova\'da Puşkin anıtının açılışında yaptığı konuşmanın önemi nedir?', 'Puşkin\'i Rus ruhunun evrenselliğinin simgesi olarak yüceltip dinleyicileri coşturması', ['Puşkin\'i Batı\'yı körü körüne taklit eden bir şair olarak sert biçimde eleştirmesi', 'Konuşmanın ardından sürgüne gönderilmesi', 'Puşkin\'in yayımlanmamış bir eserini ilk kez okuması'], 'Bu konuşmada Dostoyevski, Puşkin\'in her ulusun ruhunu kavrayabilen bir \'evrensel insan\' olduğunu söyler; konuşma büyük bir coşkuyla karşılanmıştır.'),
  ('Dostoyevski\'nin yaşamında kürek cezasının ardından gelen dönem hangisidir?', 'Semipalatinsk\'te sıradan asker olarak hizmet etmesi', ['Paris\'e kaçıp sürgünde yaşaması', 'Moskova Üniversitesi\'nde hukuk profesörü olarak ders vermesi', 'Manastıra kapanıp rahip olması'], 'Omsk\'taki dört yıllık katorgadan sonra Dostoyevski Semipalatinsk\'te asker olarak hizmet etmiş, ilk evliliğini de orada yapmıştır.'),
  ('Savaş ve Barış\'ta beklenmedik biçimde büyük bir servetin mirasçısı olan Pierre Bezuhov, ilk evliliğinin çöküşünden sonra anlam arayışıyla hangi topluluğa katılır?', 'Masonluk', ['Cizvit tarikatı', 'Dekabrist gizli örgütü', 'Eski İnananlar cemaati'], 'Pierre, Hélène ile evliliğinin yıkımından ve Dolohov\'la düellodan sonra bir yolculukta tanıştığı yaşlı bir masonun etkisiyle Masonluğa katılır; bu, anlam arayışının ilk durağıdır.'),
  ('Savaş ve Barış\'ta Fransızlara esir düşen Pierre\'e yaşamın sade anlamını öğreten köylü asker kimdir?', 'Platon Karatayev', ['Tihon Şçerbatı', 'Vasili Denisov', 'Fyodor Dolohov adlı subay'], 'Esirlik sırasında tanıştığı Platon Karatayev\'in alçakgönüllü bilgeliği Pierre\'in ruhsal dönüşümünde belirleyici olur.'),
  ('Tolstoy\'un Savaş ve Barış\'ta General Kutuzov\'u çizme biçimi, yazarın tarih görüşüyle nasıl bağlantılıdır?', 'Akışı sezip ona uyan bilge bir komutandır; birey tarihi yönlendiremez görüşüne uyar', ['Her şeyi önceden planlayan dâhi bir stratejisttir; büyük adamlar tarihi yapar görüşüne uyar', 'Korkak ve beceriksiz biridir; Rus ordusunun neden sürekli yenildiğini açıklar', 'Napolyon\'un bir kopyası gibidir; iki ulusun aslında birbirine benzediğini gösterir'], 'Tolstoy, kendini tarihin yöneticisi sanan Napolyon\'a karşı, olayların akışına saygı gösteren Kutuzov\'u yüceltir.'),
  ('Anna Karenina\'daki at yarışı sahnesinde Vronski\'nin hatası yüzünden sırtı kırılan kısrağın yaşadıkları, romanda neyin simgesi olarak okunur?', 'Vronski\'nin tutkusunun Anna\'yı yıkıma sürüklemesinin', ['Rus ordusunun Kırım\'daki yenilgisinin', 'Levin\'in köyde başlattığı tarım reformunun başarısızlığının', 'Karenin\'in bürokrasideki yükselişinin'], 'Vronski\'nin ani bir hareketiyle düşüp vurulmak zorunda kalan Frou-Frou, onun sevdiği şeye istemeden zarar verişini simgeler.'),
  ('Anna Karenina\'nın sonunda Vronski\'nin yaptığı şey nedir?', 'Gönüllü olarak Sırbistan\'daki savaşa gider', ['Kitty ile evlenip köyüne yerleşir', 'Kitty ile evlenip annesinin köydeki malikânesine yerleşir', 'Manastıra kapanıp keşiş olur'], 'Anna\'nın ölümünden sonra yıkılan Vronski, Türklere karşı savaşan Sırplara yardım için kendi parasıyla kurduğu bir birlikle cepheye gider.'),
  ('Tolstoy\'un \'Sanat Nedir?\' adlı denemesinde sanatı tanımlama biçimi hangisidir?', 'Sanatçının yaşadığı duyguyu başkalarına geçirmesi, onlara bulaştırması', ['Yalnızca güzelliğin kurallara uygun biçimde yeniden üretilmesi', 'Toplumsal sınıfların çatışmasının bilimsel ve nesnel biçimde sahnede gösterilmesi', 'Seçkin bir azınlığa hitap eden zihinsel bir oyun'], 'Tolstoy\'a göre sanat, duyguların bulaşıcı aktarımıdır; geniş halk kitlelerine ulaşamayan, salt seçkinlere hitap eden sanatı eleştirir.'),
  ('Tolstoy\'un 1901\'de yaşadığı ve dönemin kamuoyunda büyük yankı uyandıran olay hangisidir?', 'Rus Ortodoks Kilisesi tarafından aforoz edilmesi', ['Çar tarafından kont unvanının ve bütün topraklarının elinden alınması', 'Nobel Edebiyat Ödülü\'nü reddetmesi', 'Moskova Üniversitesi rektörlüğüne atanması'], 'Kilise ve dogmalar üzerine eleştirileri nedeniyle Tolstoy 1901\'de Sinod tarafından aforoz edilmiştir.'),
  ('Tolstoy\'un \'Kazaklar\' adlı romanında Moskova\'dan Kafkasya\'ya giden genç soylu Olenin\'in yaşadığı temel çatışma nedir?', 'Doğal ve yalın Kazak yaşamına özenmesine karşın ona hiçbir zaman ait olamaması', ['Kazak isyanını bastırmakla görevlendirilip bu yüzden ağır bir vicdan azabı çekmesi', 'Bir Kazak kızıyla evlenip kente dönmeyi reddetmesi', 'Kazakların kendisini casus sanıp sürgün etmesi'], 'Olenin, Maryanka\'ya âşık olur ve doğaya yakın yaşamı yüceltir; ama uygar geçmişi onu bu dünyadan hep ayrı tutar.'),
  ('Martı\'da oyuncu olmak isteyen Nina\'nın kendini sürekli \'martı\' ile özdeşleştirmesi neyi anlatır?', 'Başkasının keyfi için harcanıp yıkılan ama yine de ayakta kalmaya çalışan bir yaşamı', ['Özgürlüğe kavuşup ailesinin, kasabanın ve bütün bağlarının yükünden kurtulan mutlu bir yaşamı', 'Denize ve yolculuğa duyduğu çocukluk tutkusunu', 'Ailesinin ona miras bıraktığı soylu armayı'], 'Trigorin, \'canı sıkıldığı için\' bir martıyı öldüren adam öyküsünü düşünür; Nina da Trigorin tarafından terk edilir ama zorluklara direnerek oyunculuğu sürdürür.'),
  ('Martı\'nın 1896\'daki ilk temsili ile 1898\'deki Moskova Sanat Tiyatrosu temsili arasındaki fark nedir?', 'İlki büyük bir başarısızlıkla sonuçlanmış, ikincisi büyük başarı kazanmıştır', ['İlki yasaklanmış, ikincisi sansürle kısaltılarak oynanmıştır', 'İlki Paris\'teki bir Rus göçmen tiyatrosunda, ikincisi ise Moskova\'daki bir sarayda sahnelenmiştir', 'İlki opera olarak, ikincisi düz oyun olarak sahnelenmiştir'], 'Petersburg\'daki ilk temsilde seyirci oyunu anlamamış, Çehov büyük bir hayal kırıklığı yaşamıştır; Stanislavski ve Nemiroviç-Dançenko\'nun sahnelemesi ise zafer olmuş, martı tiyatronun simgesi olmuştur.'),
  ('Vişne Bahçesi\'nin son sahnesinde yaşlı uşak Firs\'in kilitli evde unutulması neyi düşündürür?', 'Eski düzenin kimse fark etmeden geride bırakılıp unutulduğunu', ['Yeni sahiplerin eski uşaklara iyi davrandığını ve onları asla yalnız bırakmadığını', 'Ailenin yeniden geri döneceğini', 'Firs\'in aslında malikânenin gerçek sahibi olduğunu'], 'Herkes gittikten sonra hasta Firs\'in evde unutulması ve uzaktan gelen balta sesleri, bir dönemin sessizce sona erişinin simgesidir.'),
  ('Çehov\'un \'Vişne Bahçesi\'ni nasıl nitelediği, Stanislavski\'nin sahnelemesiyle ilgili hangi anlaşmazlığı yansıtır?', 'Çehov oyunu bir komedi olarak görürken sahneleme onu ağır bir dram gibi yorumlamıştır', ['Çehov oyunu bir trajedi olarak görürken sahneleme onu vodvil gibi oynamıştır', 'Çehov oyunun müzikal olmasını istemiş, sahneleme müziği çıkarmıştır', 'Çehov oyunun kısaltılmasını istemiş, sahneleme ise oyunu neredeyse dört saatlik bir gösteriye dönüştürmüştür'], 'Çehov oyunun alt başlığına \'komedi\' yazmış ve sahnelemenin fazla gözyaşı dökücü olmasından yakınmıştır.'),
  ('Çehov\'un \'Sevimli\' (Duşeçka) öyküsündeki Olenka\'nın en belirgin özelliği nedir?', 'Her sevdiği erkeğin görüşlerini ve ilgilerini kendininmiş gibi benimsemesi', ['Hiç kimseye bağlanmadan bütün yaşamını kendi kurallarıyla, tek başına ve özgürce sürdürmesi', 'Kocalarını sırayla zehirleyip mirasa konması', 'Kenti bırakıp manastırda yaşamayı seçmesi'], 'Olenka tiyatrocu kocasıyla tiyatroyu, keresteci kocasıyla keresteyi konuşur; kendine ait bir görüşü yoktur. Tolstoy bu öyküyü özellikle sevmiştir.'),
  ('Çehov\'un 1890\'da çıktığı uzun ve zorlu yolculuk sonunda yazdığı inceleme kitabının konusu nedir?', 'Sahalin Adası\'ndaki sürgün ve kürek mahkûmlarının yaşamı', ['Kafkasya\'daki dağ köylerinde derlenen halk masalları ve türküleri', 'Moskova hastanelerindeki salgın hastalıklar', 'Kırım\'daki bağcılık ve şarap üretimi'], 'Çehov Sibirya\'yı aşarak Sahalin\'e gitmiş, binlerce mahkûmla görüşüp bir sayım yapmış ve \'Sahalin Adası\' adlı belgesel kitabı yazmıştır.'),
  ('Çehov\'un ilk yıllarda mizah dergilerine yazdığı kısa öyküler için kullandığı takma adlardan en tanınmışı hangisidir?', 'Antoşa Çehonte', ['Kozma Petroviç Prutkov', 'Maksim Gorki', 'Andrey Bely'], 'Çehov öğrenciyken ailesini geçindirmek için mizah dergilerine \'Antoşa Çehonte\' adıyla yüzlerce kısa öykü yazmıştır.'),
  ('Üç Kız Kardeş\'te ailenin evini adım adım ele geçiren ve kız kardeşleri kendi evlerinde yabancılaştıran kişi kimdir?', 'Ağabeyleri Andrey\'in karısı Nataşa', ['En küçük kardeş İrina\'nın nişanlısı', 'Hizmetçi Anfisa', 'Yarbay Verşinin\'in karısı'], 'Andrey ile evlenen kaba ve hırslı Nataşa, evin odalarını giderek kendi çocuklarına ve isteklerine göre düzenler; kız kardeşler evden dışlanır.'),
  ('Leskov\'un, Tula\'lı bir silah ustasının İngilizlerin yaptığı minik çelik pireyi nallamasını anlatan öyküsü hangisidir?', 'Solak', ['Büyülenmiş Gezgin', 'Katedral Halkı', 'Yaşlı Bir Ressamın Notları'], '\'Solak\', Rus halk zanaatkârının ustalığını mizahi ve masalsı bir dille anlatır; usta pireyi nallar ama pire artık dans edemez.'),
  ('Saltıkov-Şçedrin\'in \'Golovlev Ailesi\' romanında ikiyüzlü dindarlığı ve boş laflarıyla ailesini yıkıma götüren Porfiri\'ye verilen lakap nedir?', 'Yuduşka (Küçük Yahuda)', ['Oblomov (uykucu adam)', 'Bazarov', 'Kozma'], 'Porfiri Golovlev, tatlı sözlerle çevresindekileri soyup yalnız bırakır; ona verilen \'Yuduşka\' lakabı, İncil\'deki hain Yahuda\'ya göndermedir.'),
  ('\'Rusya akılla anlaşılmaz, sıradan bir ölçüyle ölçülmez; ona yalnızca inanılabilir\' dizeleriyle tanınan 19. yüzyıl Rus şairi kimdir?', 'Fyodor Tyutçev', ['Afanasi Fet', 'Aleksey Koltsov', 'Vasili Jukovski'], 'Tyutçev\'in bu dörtlüğü, Rus kimliği tartışmalarında en çok alıntılanan dizelerden biridir; şair felsefi doğa lirikleriyle de tanınır.'),
  ('Çernışevski\'nin hapishanede yazdığı \'Ne Yapmalı?\' romanının sonraki kuşaklar üzerindeki etkisini en iyi gösteren durum hangisidir?', 'Lenin\'in bir yapıtına aynı başlığı vermesi', ['Dostoyevski\'nin bu romanı Rusçaya çevirmesi', 'Çar\'ın romanı okul kitabı yapması', 'Tolstoy\'un romanın devamını yazması'], 'Romandaki \'yeni insanlar\' ve çivili yatakta uyuyan Rahmetov, devrimci gençlere örnek olmuş; Lenin 1902\'de yazdığı broşüre \'Ne Yapmalı?\' adını vermiştir.'),
  ('Gorki\'nin \'Ayaktakımı Arasında\' (Na dne) oyununda yoksulların sığınağına gelen gezgin Luka\'nın oyundaki işlevi nedir?', 'Umutsuz insanlara teselli edici yalanlar söyleyerek \'gerçek mi, avutucu yalan mı\' tartışmasını başlatmak', ['Sığınağın sahibini öldürüp polise teslim olmak', 'İşçileri greve çağırıp devrimci bir örgüt kurmak', 'Sığınaktakilere uzak bir akrabasından miras kalan parayı dağıtıp onları kentin dışındaki bir çiftliğe götürmek'], 'Luka herkese umut verir ama ortadan kaybolunca bir kişi kendini asar; Satin\'in \'İnsan, bu kulağa ne gururlu geliyor!\' sözü bu tartışmanın karşı ucudur.'),
  ('Kuprin\'in 1905\'te yayımlanan \'Düello\' romanı hangi dünyayı eleştirel bir gözle anlatır?', 'Bir taşra kasabasındaki çarlık ordusunun subay yaşamını', ['Petersburg\'daki üniversite öğrencilerinin gizli örgütlerini', 'Sibirya\'daki altın madencilerini', 'Moskova\'daki tüccar ailelerinin evlilik pazarlıklarını'], 'Teğmen Romaşov\'un gözünden subayların can sıkıntısı, içkisi ve askerlere yapılan zulüm anlatılır; roman düelloyla biter.'),
  ('Leonid Andreyev\'in \'Asılan Yedi Kişinin Hikâyesi\' adlı yapıtı hangi konuyu işler?', 'İdama mahkûm edilen kişilerin ölümü bekleyişteki iç dünyalarını', ['Yedi kardeşin mirası paylaşamamasını', 'Yedi askerin bir köprüyü savunmasını', 'Yedi öğrencinin bir yıl boyunca tuttuğu ve sonradan yayımlanan ortak günlüğü'], 'Andreyev, beş devrimci ve iki sıradan suçlunun idamdan önceki son günlerini anlatarak ölüm cezasına karşı güçlü bir insani tavır ortaya koyar.'),
  ('Saltıkov-Şçedrin\'in \'Bir Kentin Tarihi\' adlı yapıtı nasıl bir eserdir?', 'Glupov adlı hayalî bir kentin valilerini anlatarak Rus yönetimini hicveden bir yergi', ['Moskova\'nın kuruluşunu arşiv belgelerine dayanarak ayrıntılı biçimde anlatan bilimsel bir tarih kitabı', 'Petersburg\'un mimarisini anlatan bir gezi yazısı', 'Bir kasaba papazının günlüklerinden oluşan bir roman'], '\'Glupov\', Rusçada \'aptal\' sözcüğünü çağrıştırır; eser, birbirinden saçma valilerin hükümdarlığını tarih yazımı parodisiyle anlatır.'),
  ('Aleksandr Blok\'un 1918\'de yazdığı \'On İki\' adlı uzun şiirinde, kar fırtınasında Petrograd sokaklarında yürüyen on iki Kızıl Muhafız\'ın önünde beklenmedik biçimde kim belirir?', 'İsa', ['Çar II. Nikolay\'ın hayaleti', 'Puşkin\'in bronz heykeli', 'Bir Kazak atamanı ile atlıları'], 'Şiirin son dizelerinde devrimci devriyenin başında İsa görünür; bu imge devrimin kutsal mı yoksa yıkıcı mı olduğu konusunda bugün de tartışılır.'),
  ('Rus fütüristlerinin 1912 tarihli \'Halkın Beğenisine Bir Tokat\' bildirisinde Puşkin, Dostoyevski ve Tolstoy için önerdikleri şey nedir?', 'Çağdaşlık gemisinden atılmaları', ['Okul kitaplarında daha çok yer almaları', 'Anıtlarının bütün kentlere dikilmesi', 'Eserlerinin yeni bir alfabeyle yeniden basılması'], 'Bildiri, geçmişin büyük yazarlarını \'çağdaşlığın vapurundan atmayı\' önerir; Mayakovski de bildiriyi imzalayanlar arasındadır.'),
  ('Mayakovski\'nin 1915\'te yayımlanan ve aşk, sanat, düzen ve din üzerine dört \'Kahrolsun!\' çığlığı üzerine kurulan uzun şiiri hangisidir?', 'Pantolonlu Bulut', ['Tahtakurusu', 'Hamam', 'Omurga Flütü'], '\'Pantolonlu Bulut\' Mayakovski\'nin erken döneminin başyapıtıdır; \'Tahtakurusu\' ve \'Hamam\' ise onun Sovyet bürokrasisini hicveden oyunlarıdır.'),
  ('Osip Mandelştam\'ın tutuklanıp sürgüne gönderilmesinin ve sonunda bir geçiş kampında ölmesinin doğrudan nedeni olarak bilinen şiiri nedir?', 'Stalin\'i alaya alan kısa bir yergi şiiri', ['Çarlık ailesini öven bir kaside', 'Lenin\'in ölümüne yazdığı bir ağıt', 'Kızıl Ordu için yazdığı bir marş'], 'Mandelştam 1933\'te Stalin\'i \'Kremlin dağlısı\' olarak betimleyen bir şiir yazıp dostlarına okumuş, 1934\'te tutuklanmış ve 1938\'de kampta ölmüştür.'),
  ('Bulgakov\'un \'Usta ile Margarita\' romanında Woland\'ın çevresinde yer alan, iki ayağı üstünde yürüyen ve konuşan dev kara kedinin adı nedir?', 'Behemot', ['Azazello', 'Korovyev', 'Hella'], 'Woland\'ın maiyetinde Korovyev, Azazello, cadı Hella ve kedi Behemot vardır; Behemot romanın en çok sevilen mizahi kişisidir.'),
  ('İsaak Babel\'in \'Kızıl Süvari\' öykü kitabı hangi deneyime dayanır?', '1920 Sovyet-Polonya Savaşı\'nda Budyonni\'nin süvari ordusunda muhabir olarak bulunmasına', ['Birinci Dünya Savaşı\'nda Fransa cephesindeki hemşirelik yıllarına', 'Sibirya\'da bir çalışma kampında geçirdiği sekiz yıla', 'Odessa limanında hamal olarak çalıştığı gençliğine'], 'Babel, Kızıl Süvari Ordusu\'nun yanında savaş muhabiri olarak bulunmuş; şiddetin ve güzelliğin yan yana durduğu kısa, yoğun öyküler yazmıştır.'),
  ('Andrey Platonov\'un \'Çukur\' romanında işçilerin kazdıkları dev temel çukuru neyin ironik simgesidir?', 'Hiç yükselmeyen ütopik bir \'proleter evi\'nin ve kolektivizasyonun umutsuzluğunun', ['Sovyet sanayisinin dünyaya üstünlüğünün', 'Köylülerin gömdüğü altınların', 'Kilisenin yıkılıp yerine okul yapılmasının'], 'Ortak bir proleter yapısının temeli kazılır ama çukur genişledikçe umut yerine mezar imgesine dönüşür; roman Stalin dönemi ütopyasını eleştirir.'),
  ('Doktor Jivago\'nun ilk kez yayımlandığı ülke hangisidir?', 'İtalya', ['Sovyetler Birliği', 'Fransa', 'Amerika Birleşik Devletleri'], 'Sovyetlerde yayımlanamayan roman, elyazması gizlice yurt dışına çıkarıldıktan sonra 1957\'de Milano\'da yayıncı Feltrinelli tarafından İtalyanca basılmıştır.'),
  ('Soljenitsin\'in \'İvan Denisoviç\'in Yaşamında Bir Gün\'ünün 1962\'de Sovyetler Birliği\'nde yayımlanabilmesi hangi siyasal ortamın sonucudur?', 'Kruşçev döneminde Stalin\'in eleştirilmesine izin verilen \'yumuşama\'', ['Brejnev döneminde sansürün tümüyle kaldırılması', 'Gorbaçov\'un açıklık (glasnost) politikası', 'Lenin döneminde basın özgürlüğünün tanınması'], 'Eser Kruşçev\'in onayıyla Novy Mir dergisinde yayımlanmıştır; sonraki dönemde Soljenitsin\'in yapıtları yeniden yasaklanmıştır.'),
  ('1964\'te Leningrad\'da \'toplumsal asalaklık\' suçlamasıyla yargılanan, sonra sürgüne gönderilen ve 1987\'de Nobel kazanan Rus şair kimdir?', 'İosif Brodski', ['Yevgeni Yevtuşenko', 'Andrey Voznesenski', 'Bulat Okudjava'], 'Brodski, düzenli bir işi olmadığı gerekçesiyle yargılanmış, 1972\'de ülkeden çıkarılmış ve ABD\'de yaşamıştır.'),
  ('Kutsal Kâse (Graal) motifini Avrupa edebiyatına ilk kez sokan, yarım kalmış Orta Çağ romansı hangisidir?', 'Chrétien de Troyes\'un \'Perceval\'i', ['Roland\'ın Şarkısı', 'Gül Romanı\'nın ilk bölümü', 'Tilki Renart\'ın Romanı'], 'Chrétien de Troyes\'un 12. yüzyılın sonunda yazdığı \'Perceval ya da Graal\'ın Öyküsü\', Kâse motifinin bilinen ilk edebî örneğidir.'),
  ('13. yüzyılda iki ayrı yazar tarafından yazılan ve aşkı bir bahçede gül arayışı olarak alegorik biçimde anlatan Fransız yapıtı hangisidir?', 'Gül Romanı', ['Tilki Renart\'ın Romanı', 'Aucassin ile Nicolette', 'Rolandın Şarkısı'], 'Guillaume de Lorris\'in başlattığı, Jean de Meun\'ün sürdürdüğü Gül Romanı, Orta Çağ\'ın en çok okunan alegorik yapıtlarındandır.'),
  ('Montaigne\'in \'Denemeler\'inde yakın dostu La Boétie ile arkadaşlığını açıklarken kullandığı ünlü söz hangisidir?', 'Çünkü o oydu, çünkü ben bendim.', ['Dostum, ikinci benliğimdir ve onu kaybeden kendini kaybeder.', 'Gerçek dost kara günde belli olur.', 'Dostluk iki bedende yaşayan tek ruhtur.'], 'Montaigne, dostluğun nedenini açıklayamayacağını, onu ancak \'o oydu, ben bendim\' diye anlatabileceğini söyler; Étienne de La Boétie genç yaşta ölmüştür.'),
  ('Corneille\'in, Romalı Horatius kardeşler ile Albalı Curiatius kardeşler arasındaki ölümcül dövüşü konu alan tragedyası hangisidir?', 'Horace', ['Cinna', 'Polyeucte', 'Nicomède'], '\'Horace\'ta vatan görevi ile aile ve aşk bağları çatışır; kazanan Horace, düşmana yas tutan kız kardeşini öldürür.'),
  ('La Bruyère\'in iki büyük Fransız tragedya yazarını karşılaştırırken yaptığı ünlü ayrım hangisidir?', 'Corneille insanları olmaları gerektiği gibi, Racine ise oldukları gibi çizer', ['Racine kahramanları tanrılar gibi, Corneille ise hayvanlar gibi çizer', 'Corneille yalnız komedi, Racine ise yalnız tragedya yazar', 'Racine konusunu tarihten, Corneille ise yalnızca mitolojiden alır'], 'Corneille\'in kahramanları ödev ve iradeyle tutkularını yener; Racine\'in kahramanları ise tutkularının kurbanıdır. La Bruyère bu farkı \'Karakterler\'inde özetlemiştir.'),
  ('Racine\'in genç Nero\'nun bir canavara dönüşmeye başlamasını anlattığı tragedyası hangisidir?', 'Britannicus', ['Bérénice', 'Iphigénie', 'Mithridate'], '\'Britannicus\'ta Nero, rakibi ve üvey kardeşi Britannicus\'u zehirletir; Racine oyunda iktidar hırsının doğuşunu inceler.'),
  ('Racine\'in tiyatrodan uzun süre çekildikten sonra yazdığı \'Esther\' ve \'Athalie\' tragedyalarının özelliği nedir?', 'Saint-Cyr\'deki kız okulu öğrencileri için Kutsal Kitap\'tan alınmış konularla yazılmalarıdır', ['İkisinin de düzyazıyla ve halk dilinde yazılmış komediler olmasıdır', 'İkisinin de Kral XIV. Louis tarafından yasaklanmasıdır', 'İkisinin de antik Yunan oyunlarının sözcüğü sözcüğüne çevirisi olmasıdır'], 'Madame de Maintenon\'un isteğiyle Saint-Cyr\'deki soylu kızlar okulu için yazılan bu oyunlar konularını Eski Ahit\'ten alır.'),
  ('Racine\'in tragedyalarında sıkça görülen \'tutkunun insanı kaçınılmaz biçimde yıkıma sürüklemesi\' anlayışının, gençliğinde yetiştiği hangi dinsel çevreyle ilişkilendirildiği bilinir?', 'Port-Royal\'deki Jansenist çevre', ['Cizvit kolejlerinin akılcı eğitimi', 'Kalvinist Cenevre kilisesi', 'Fransisken tarikatının yoksulluk ülküsü'], 'Racine, insan doğasının günaha yatkın olduğunu ve kurtuluşun yalnızca Tanrı\'nın lütfuyla mümkün olduğunu savunan Jansenistlerin Port-Royal okulunda yetişmiştir.'),
  ('Tartuffe\'ün 1664\'teki ilk sahnelenişinden sonra yıllarca yasaklanmasının asıl nedeni nedir?', 'Dindar çevrelerin oyunu dine saldırı olarak görmesi', ['Kralın kişisel olarak hicvedilmesi', 'Oyunun Latince yazılmış olması ve halk tarafından anlaşılamaması', 'Oyundaki müstehcen sahneler'], 'Dinî çevreler, dindarlık maskesi altında çıkar sağlayanları gösteren oyunu dine saldırı saydı; yasak ancak 1669\'da kalkabildi.'),
  ('Pascal\'ın \'Düşünceler\' adlı eserindeki ünlü \'bahis\' (pari) argümanı neyi savunur?', 'Tanrı\'ya inanmanın, kazanç ve kayıp hesabı açısından akılcı olduğunu', ['Tanrı\'nın varlığının matematiksel olarak kesin biçimde kanıtlanabildiğini göstermeyi', 'Aklın inançtan daha güvenilir olduğunu', 'Doğanın boşluktan korktuğunu'], 'Pascal, Tanrı\'nın varlığı kanıtlanamasa da inanmanın sonsuz kazanç, inanmamanın büyük risk getirdiğini ileri sürerek inancı bir bahis gibi sunar.'),
  ('Pascal\'ın \'Taşra Mektupları\' (Les Provinciales) hangi kesime karşı yazılmış polemik mektuplardır?', 'Cizvitlere', ['Protestanlara', 'Krala', 'Akademi üyelerine'], 'Pascal, Jansenist dostlarını savunmak için, Cizvitlerin ahlak anlayışını ve Sorbonne\'un Arnauld\'ya karşı tutumunu mizahla eleştiren mektuplar yayımlamıştır.'),
  ('Boileau\'nun \'Şiir Sanatı\' (L\'Art poétique) eserinin klasisizm açısından önemi nedir?', 'Akıl, doğallık ve kurallara dayalı klasik ölçütleri dize halinde sistemleştirmesi', ['Romantik özgürlüğü ve kuralsız yaratıcılığı öne çıkaran bir manifesto niteliğinde olması', 'Halk şiirini yüceltmesi', 'Serbest nazmı önermesi'], '1674\'te yayımlanan didaktik şiir, \'önce akıl\' diyen, antik modellere bağlı klasik estetiğin bildirisi sayılır.'),
  ('Voltaire\'in \'Felsefe Mektupları\' (İngiliz Mektupları) niçin Fransa\'da yasaklanıp yakılmıştır?', 'İngiliz toplumunu över görünerek Fransa\'daki baskıyı ve dinî kuralları eleştirdiği için', ['Latince yazılıp halkın anlayamayacağı bir dille hazırlandığı ve kutsal metinleri eleştirdiği için', 'Krala ağır hakaretler içerdiği için', 'Gizli ordu planları anlattığı için'], 'Eser, İngiltere\'deki dinî hoşgörü ve düşünce özgürlüğünü örnek göstererek dolaylı biçimde Fransız rejimini eleştirir.'),
  ('Diderot\'nun \'Jacques Fatalist ve Efendisi\' romanının anlatım tekniğindeki yenilik nedir?', 'Anlatıcının okurla konuşup olay akışını sık sık kesmesi ve geleneksel kurguyla oynaması', ['Tüm olayların tek bir uzun mektup içinde, kronolojik sırayla ve yazarın görünmediği biçimde verilmesi', 'Sahne talimatlarıyla yazılması', 'Yalnız şiirle anlatılması'], 'Diderot, okurla tartışan anlatıcı ve iç içe geçen hikâyelerle romanın kurallarını bilinçli biçimde bozar; bu yüzden çağının ilerisinde sayılır.'),
  ('Diderot\'nun \'Rameau\'nun Yeğeni\' yapıtı hangi biçimde yazılmıştır?', 'İki kişi arasındaki felsefi bir diyalog', ['Üç perdelik, manzum bir komedi', 'Orta Çağ tarzı manzum destan', 'Yazarın yolculuk günlüğü biçiminde'], 'Yazar (\'Ben\') ile ünlü bestecinin yeğeni \'O\' arasındaki sohbet, ahlak, sanat ve toplum üzerine ironik bir tartışmaya dönüşür.'),
  ('Marivaux\'nun komedilerinde sık işlenen tema ve \'marivaudage\' kavramı neyi anlatır?', 'Âşıkların duygularını inceliklerle, oyunlarla ve sözcük oyunlarıyla keşfetmesini', ['Kralın saray entrikalarını', 'Bir kasabadaki yoksulluğu', 'Tarihî savaşları'], 'Marivaux\'nun \'Aşkın ve Rastlantının Oyunu\' gibi oyunlarında rol değiştirme ve zarif sözle aşk incelenir; üslup \'marivaudage\' diye anılır.'),
  ('Laclos\'nun \'Tehlikeli İlişkiler\' romanında Valmont ile Marquise de Merteuil\'in oynadığı oyunun biçimi ve yapısı nedir?', 'Mektuplarla anlatılan bir baştan çıkarma ve intikam oyunu', ['Gemi seferi günlüğü', 'Kutsal kitap yorumu', 'Kasaba tarihi'], 'Roman mektup biçimindedir; iki soylu, aşkı bir strateji gibi kullanarak çevrelerindeki insanları yıkar. Anlatım çok sesli ve ironiktir.'),
  ('Hugo\'nun III. Napolyon\'u hedef alan sert hiciv şiirlerinden oluşan kitabı hangisidir?', 'Cezalar (Les Châtiments)', ['Doğu Şiirleri (Les Orientales)', 'Yüzyılların Efsanesi (La Légende des siècles)', 'Tefekkürler (Les Contemplations)'], '1853\'te Brüksel\'de yayımlanan \'Cezalar\', imparatora karşı öfke dolu şiirlerle doludur ve Fransa\'ya sokulması yasaklanmıştır.'),
  ('Hugo\'nun Vendée ayaklanmasını ve devrim ile gelenek çatışmasını işleyen son romanı hangisidir?', 'Doksan Üç', ['Gülen Adam', 'Denizin İşçileri', 'Han d\'Islande'], '1874\'te yayımlanan roman, 1793\'te Cumhuriyetçilerle Kralcılar arasındaki çatışmayı Gauvain, Lantenac ve Cimourdain üzerinden işler.'),
  ('Hugo\'nun \'Tefekkürler\' (Les Contemplations) kitabının duygusal ağırlık merkezi hangi olayla ilgilidir?', 'Kızı Léopoldine\'in boğularak ölmesiyle', ['Eşi Adèle\'in sadakatsizliğiyle', 'Napolyon ordusunun Waterloo\'daki yenilgisiyle', 'Fransa\'dan sürgün edilme kararıyla'], '1843\'te Léopoldine ve eşi Seine\'de boğuldu; kitabın ikinci yarısındaki şiirler bu kayba duyulan acıyı anlatır.'),
  ('Dumas\'nın çok sayıda yapıt vermesini açıklayan ve eleştirilere yol açan çalışma yöntemi hangisiydi?', 'Maquet gibi yardımcılarla ortak çalışıp romanlarını tefrika olarak yazması', ['Eserlerini yalnız şiirle yazması', 'Çevirileri kendi adıyla yayımlaması', 'Eserlerini sahnede doğaçlama anlatması'], 'Dumas gazete tefrikası için çalışan bir \'atölye\' kurmuş; Auguste Maquet gibi yardımcılar taslak ve kurguya katkı yapmıştır.'),
  ('Mérimée\'nin edebiyat dışında Fransız kültürüne en önemli katkısı hangisidir?', 'Tarihî anıtlar müfettişi olarak yapıların korunmasına öncülük etmesi', ['Fransız Akademisi\'ni kurması', 'İlk Fransız ansiklopedisini hazırlaması', 'Paris Operası\'nı yönetmesi'], 'Mérimée 1834\'ten itibaren Tarihî Anıtlar Genel Müfettişi olarak Fransa\'daki kilise ve kalelerin korunmasında önemli rol oynadı.'),
  ('George Sand\'ın köy yaşamına yönelen \'Şeytan Bataklığı\' gibi romanları hangi eğilimi temsil eder?', 'Kırsal yaşamı idealize eden pastoral romanı', ['Bilimsel gözleme dayalı natüralist roman', 'Cinayet çözmeye yönelen polisiye roman', 'Makine çağını öven fütürist anlatı'], 'Sand, Berry bölgesindeki köylülerin yaşamını sade ve içten bir dille anlatan \'köy romanları\' yazdı.'),
  ('Musset\'nin \'Lorenzaccio\' adlı oyununun kahramanı nasıl bir ikilem yaşar?', 'Zorbayı öldürerek halkı kurtarmayı düşünürken kendi yozlaşmışlığıyla yüzleşir', ['Tahtı bırakıp keşiş olur', 'Savaşa gitmek ister ama hasta düşer', 'Kardeşiyle taht kavgası yapar'], 'Floransa Dükü\'nü öldüren Lorenzo, bu eylemin halk için bir şey değiştirmediğini görür; oyun romantik dramanın başyapıtlarındandır.'),
  ('Gérard de Nerval\'in \'Sylvie\' ve \'Aurélia\' gibi yapıtlarını özellikle belirleyen unsur hangisidir?', 'Rüya, bellek ve gerçek arasındaki geçişler', ['Köylü yaşamının nesnel ve gerçekçi dökümü', 'Savaş sahnelerinin ayrıntılı betimlenişi', 'Hukuk davalarının adım adım incelenmesi'], 'Nerval\'in yazıları rüya ile gerçeği, çocukluk anılarıyla ideal sevgili figürünü karıştırır; sembolizm ve gerçeküstücülüğün öncülerinden sayılır.'),
  ('Stendhal\'in \'Aşk Üzerine\' adlı denemesinde âşıkların sevgiliyi yüceltmesini anlatan \'kristalleşme\' benzetmesi neyi gösterir?', 'Âşığın sevgiliye hayalinde kusursuz nitelikler yüklemesini', ['Aşkın aile baskısıyla donmasını', 'Paranın sevgiyi öldürmesini', 'Evliliğin sıkıcı hâle gelmesini'], 'Stendhal, tuz madeninde dala yapışan kristallerin onu pırıl pırıl göstermesi gibi, aşkın sevgiliyi bütün kusurlarıyla birlikte güzelleştirdiğini söyler.'),
  ('Balzac\'ın \'İnsanlık Komedyası\' kitaplarında aynı kişilerin farklı romanlarda yeniden görünmesi (personnages reparaissants) anlatıya ne kazandırır?', 'Bütünlüğü olan, canlı ve gerçeğe benzeyen bir toplum evreni', ['Çok sayıda ayrı tarihî dönem', 'Her romanın bağımsız kalmasını', 'Sürekli yabancı ülke dekoru'], 'Rastignac, Vautrin gibi kişiler birçok kitapta belirir; böylece okur Fransız toplumunun geniş bir haritasını görür.'),
  ('Balzac\'ın \'Tılsımlı Deri\' romanında Raphaël\'in sahip olduğu derinin sihirli özelliği nedir?', 'Her dilek yerine geldikçe deri küçülür ve sahibinin ömrü kısalır', ['Sahibini görünmez yapar', 'Yalnızca para kazandırır', 'Ölümsüzlük verir'], 'Deri istekleri gerçekleştirir ama her istekte küçülür; Balzac, tutkuların insan ömrünü tükettiğini bu fantastik kurguyla işler.'),
  ('Balzac\'ın \'Yitik Hayaller\' romanında taşralı genç şair Lucien de Rubempré\'nin Paris\'te yaşadığı temel hayal kırıklığı hangisidir?', 'Gazetecilik ve edebiyat dünyasının para ve çıkar ilişkileriyle işlediğini görmesi', ['Ordudan atılması', 'Kardeşinin ihaneti', 'Hapishanede unutulması'], 'Lucien\'in yeteneği, gazete ve yayın dünyasının yozlaşmasında erir; roman, sanat dünyasındaki çıkar mekanizmalarının eleştirisidir.'),
  ('Flaubert\'in \'Üç Öykü\' kitabındaki \'Yalın Bir Yürek\' öyküsünün kahramanı Félicité\'nin yaşamındaki en önemli duygusal bağ hangisidir?', 'Papağanı Loulou', ['Evlendiği asker', 'Kızı', 'Çalıştığı evin torunu'], 'Yoksul hizmetçi Félicité, sevdiklerini art arda kaybeder ve ölürken bile papağanını Kutsal Ruh sanır.'),
  ('Flaubert\'in \'Hazır Fikirler Sözlüğü\' hangi tutumu alaya alır?', 'Burjuvanın ezber ve klişelerle düşünmesini', ['Yabancı dil öğretimi yöntemlerini', 'Askerî jargonu ve subay dilini', 'Şiir yazım kurallarını ve kalıplarını'], 'Flaubert, her konuda kalıplaşmış görüşleri alfabetik bir sözlük biçiminde yazarak \'budalalık\' diye adlandırdığı toplumsal tutumu eleştirir.'),
  ('Flaubert, Madame Bovary\'yi yazarken hangi anlatı tutumunu savunmuştur?', 'Yazarın eserin içinde görünmeden, doğa gibi her yerde var olup hiçbir yerde görünmemesi', ['Okuru açıkça yönlendirmesi', 'Kahramanıyla aynı görüşü paylaşması', 'Her bölümde ahlaki sonuç çıkarması'], 'Flaubert\'e göre yazar, evrendeki Tanrı gibi eserinde her yerde hissedilmeli ama görünmemelidir; bu, nesnel ve kişisel olmayan anlatı ilkesidir.'),
  ('Zola\'nın \'Kadınların Mutluluğu\' (Au Bonheur des Dames) romanı hangi yeni olguyu işler?', 'Büyük mağazaların küçük esnafı yok etmesini', ['Kömür madenciliğinin yaygınlaşmasını', 'Tarımın makineleşmesini ve köylerin boşalmasını', 'Matbaanın yaygınlaşmasının etkilerini'], 'Roman, Paris\'te yeni doğan büyük mağaza kapitalizminin küçük dükkânları nasıl sildiğini anlatır.'),
  ('Zola\'nın \'Thérèse Raquin\' romanına yazdığı önsözün önemi nedir?', 'Natüralizmin ilke bildirisi olarak görülmesi', ['Romantik drama anlayışını savunması', 'Mektup romanı biçiminin övülmesi olarak', 'Tarihî romanın kurallarını belirlemesi'], '1867 tarihli bu önsözde Zola, insanları fizyolojik ve çevresel etkilere göre inceleyen \'bilimsel\' bir yazım anlayışını savunur.'),
  ('Zola, \'Deneysel Roman\' kuramında hangi bilim insanının yöntemini edebiyata uyarlamak ister?', 'Claude Bernard', ['Charles Robert Darwin ve evrim kuramı', 'Louis Pasteur ve mikrop kuramı', 'Auguste Comte ve pozitivizm'], 'Zola, Bernard\'ın deneysel tıp yöntemini örnek alarak romancıyı \'gözlemci ve deneyci\' sayar.'),
  ('Huysmans\'ın \'Tersine\' (À rebours) romanındaki kahraman Des Esseintes\'in yaşam tarzı nasıl nitelenir?', 'Toplumdan kaçıp yapay ve rafine bir estetik dünya kuran dekadan', ['Doğaya dönen köylü', 'Devrimci işçi', 'Savaş gazisi'], 'Des Esseintes, toplumdan uzaklaşıp sanat nesneleri ve duyu deneyleriyle dolu bir evde yaşar; roman dekadanlığın simge yapıtıdır.'),
  ('Zola\'nın \'Toprak\' (La Terre) romanında ele aldığı çevre hangisidir?', 'Köylülerin toprak hırsı ve kıskançlıklarıyla dolu kırsal yaşam', ['Paris sosyetesi', 'Maden işçileri', 'Askerî kışla'], 'Roman, köylü ailenin toprağın paylaşımı uğruna şiddete varan çatışmalarını sert biçimde anlatır; Zola çok eleştirilmiştir.'),
  ('Maupassant\'ın \'Hayat\' (Une vie) romanının kahramanı Jeanne\'ın yaşamı nasıl özetlenebilir?', 'Umutlarla başlayıp eşinin ihanetleri ve kayıplarla kırılan bir yaşam', ['Tarihî bir savaş anlatısı', 'Bir maceraperestin yolculuğu', 'Siyasi bir yükseliş'], 'Jeanne, evliliğindeki hayal kırıklığı ve oğlunun yüzünden yaşadığı acılara rağmen sonunda yaşamda küçük bir teselli bulur.'),
  ('Zola\'nın Dreyfus olayındaki tavrı onu hangi sonuçla karşı karşıya bıraktı?', 'Hakaretten mahkûm olup İngiltere\'ye kaçması', ['Fransız Akademisi\'ne üye seçilmesi', 'Cumhurbaşkanının yakın dostu olması', 'Askerlik görevini tamamlaması'], '\'Suçluyorum!\' yazısı yüzünden hapis cezası alan Zola, cezadan kaçmak için bir süre İngiltere\'de yaşadı.'),
  ('Parnas okulunun öncü şairlerinden olan ve \'Barbar Şiirler\' kitabıyla tanınan şair kimdir?', 'Leconte de Lisle', ['Sully Prudhomme, ilk Nobel sahibi', 'Paul Éluard, gerçeküstücü şair', 'Jacques Prévert, sinemacı şair'], 'Leconte de Lisle, antik Yunan ve Hint mitolojilerini soğuk ve nesnel bir dille işleyen Parnas şiirinin başlıca temsilcisidir.'),
  ('Baudelaire\'in \'Uyumlar\' (Correspondances) sonesinde \'Doğa bir tapınaktır\' fikriyle başlayan görüş hangisidir?', 'Duyuların ve görünür dünyanın ardında gizli bir uyum ve simge ağı bulunduğu', ['Doğanın yıkıcı olduğu', 'Şiirin akıl dışı kurallarla yazılması gerektiği', 'Aşkın tek gerçek olduğu'], 'Soneden esinlenen sembolistler, her şeyin birbiriyle gizli bağlarla bağlı olduğunu ve şairin bu simgeleri çözmesi gerektiğini savunur.'),
  ('Baudelaire\'in nesir şiirlerinden oluşan kitabı hangisidir?', 'Paris Sıkıntısı (Le Spleen de Paris)', ['Yapay Cennetler (Les Paradis artificiels)', 'Kötü Bir Dua (Mauvaise prière)', 'Kentin Işıkları (Les Lumières de la ville)'], '\'Paris Sıkıntısı\', kent yaşamını kısa düzyazı şiirlerle anlatır; modern kent şiirinin öncü örneklerindendir.'),
  ('Mallarmé\'nin \'Zar Atımı\' (Un coup de dés) şiirini özgün kılan özellik nedir?', 'Sayfa düzeni, boşluklar ve yazı boyutlarının anlamın parçası olması', ['Yüz dörtlükten oluşması', 'Tamamen Latince yazılması', 'Her dizesinin kafiyeli olması'], 'Şair, sözcükleri sayfaya dağıtarak görsel bir düzen kurar; bu yöntem sonraki modern şiir deneylerini etkilemiştir.'),
  ('\'Maldoror\'un Şarkıları\'nın yazarı Lautréamont\'un gerçek adı nedir?', 'Isidore Ducasse', ['Jules Laforgue', 'Tristan Corbière', 'Henri de Régnier'], 'Uruguay doğumlu Ducasse, genç yaşta ölmüş; eseri gerçeküstücüler tarafından keşfedilip yüceltilmiştir.'),
  ('Rimbaud\'nun \'Ben bir başkasıdır\' (Je est un autre) sözü şiir anlayışı bakımından neyi anlatır?', 'Şairin kendi bilinçdışına ve algı sınırlarının ötesine açılarak \'görücü\' olması gerektiğini', ['Başkalarının şiirlerini kopyalama', 'Takma ad kullanmanın önemini', 'Sahne oyunculuğunu'], '\'Görücü mektupları\'nda Rimbaud, şairin bütün duyularını düzensizleştirerek bilinmeyene ulaşması gerektiğini söyler.'),
  ('Rimbaud\'nun şiiri bıraktıktan sonra yaşamının büyük bölümünü hangi bölgede geçirdiği bilinir?', 'Doğu Afrika', ['Güney Amerika\'nın yağmur ormanları', 'Avustralya\'nın altın bölgeleri', 'Hindistan\'ın Bombay limanı'], 'Rimbaud, ticaret ve silah işleriyle uğraştı; hastalanıp Marsilya\'da bacağının kesilmesinin ardından 37 yaşında öldü.'),
  ('Verlaine\'in \'Sonbahar Şarkısı\' şiirinin dizeleri İkinci Dünya Savaşı sırasında hangi amaçla kullanılmıştır?', 'Müttefiklerin çıkarma öncesi Fransız Direnişi\'ne şifreli mesaj vermesi için', ['Radyo reklamları için', 'Askerî marş olarak', 'Okullarda ezber için'], 'BBC, Normandiya Çıkarması\'nın yaklaştığını Direniş\'e bildirmek üzere \'Sonbaharın uzun hıçkırıkları...\' dizesini yayınladı.'),
  ('Alfred Jarry\'nin \'Ubu Kral\' oyununun 1896\'daki ilk temsili neden skandal yarattı?', 'Kaba ve saçma dil, karikatürize kral figürü ve burjuva ahlakını aşağılaması yüzünden', ['Oyunun Almanca sahnelenmesi yüzünden', 'Tamamen sessiz oynanması yüzünden', 'Gerçek bir cinayeti anlatması yüzünden'], 'Oyun \'Merdre\' (pislik) sözüyle başlayınca seyirci karıştı; Ubu, sonraki absürt tiyatronun öncülerinden sayılır.'),
  ('André Gide\'in \'Sahte Para Basımcıları\' romanının biçimsel yeniliği nedir?', 'Romanın içinde roman yazan bir yazar kahramana yer vermesi', ['Yalnızca mektuplardan oluşması', 'Tek paragraftan oluşması', 'Manzum yazılması'], 'Edouard adlı yazarın \'Sahte Para Basımcıları\' adlı roman tasarlaması, anlatının kendi üzerine düşünmesini sağlayan öncü bir kurgudur.'),
  ('Proust\'a 1919\'da Goncourt Ödülü\'nü kazandıran cilt hangisidir?', 'Çiçek Açmış Genç Kızların Gölgesinde', ['Guermantes Tarafı', 'Sodom ve Gomore', 'Mahpus'], 'Dizinin ikinci cildi, anlatıcının Balbec\'teki yazı ve Albertine ile tanışmasını konu alır; ödüle değer görüldü.'),
  ('Romain Gary\'nin yazın tarihinde benzersiz sayılan başarısı nedir?', 'Goncourt Ödülü\'nü ikinci kez başka bir adla (Émile Ajar) kazanması', ['İki kez Nobel alması', 'Fransız Akademisi başkanı olması', 'İlk Fransız astronotu olması'], 'Gary, 1956\'da kendi adıyla, 1975\'te Émile Ajar takma adıyla aynı ödülü kazandı.'),
  ('Camus\'nün \'Düşüş\' (La Chute) romanı hangi anlatı kurgusuna dayanır?', 'Amsterdam\'da bir barda, eski avukat Clamence\'ın suçluluk itirafı', ['Bir savaş günlüğü', 'Bir mahkeme tutanağı', 'Bir devlet raporu'], 'Clamence, bir kadının nehre atlayışına tepkisiz kaldığı anı itiraf ederken dinleyiciyi de kendi suçluluğuyla yüzleştirir.'),
  ('Camus\'nün \'Caligula\' oyununda imparator Caligula\'nın zorbalığı nasıl gerekçelendirilir?', 'Sevdiği kız kardeşinin ölümüyle dünyanın absürtlüğünü fark edip sınırsız özgürlük denemesine girişir', ['Ordudan gelen baskıyla', 'Din değiştirmesiyle', 'Hastalıktan delirmesiyle'], 'Caligula, ölümün kaçınılmazlığı karşısında her şeyin mümkün olduğunu göstermek için zorbalığa kayar.'),
  ('Camus ile Sartre\'ın 1952\'de açık bir kopuşa varmasına yol açan tartışma hangi eser çevresinde yaşandı?', 'Başkaldıran İnsan', ['Bulantı (La Nausée) romanı', 'Yabancı (L\'Étranger) romanı', 'Duvar (Le Mur) öykü kitabı'], 'Les Temps Modernes dergisinde yer alan eleştiriler, Camus\'nün totaliter eğilimlere karşı tavrı yüzünden iki yazarı ayırdı.'),
  ('Sartre\'ın \'Sinekler\' adlı oyunu hangi mitolojik hikâyeden yola çıkar?', 'Orestes\'in babasının intikamını alması', ['Prometheus\'un ateşi çalıp insana vermesi', 'Odysseus\'un Ithaka\'ya dönüşü', 'Sisifos\'un kayayı yuvarlama cezası'], 'Sartre, Orestes mitiyle Alman işgali altındaki Fransa\'ya gönderme yaparak özgürlük ve sorumluluk temasını işler.'),
  ('Sartre\'ın \'kötü niyet\' (mauvaise foi) kavramı neyi anlatır?', 'İnsanın özgürlüğünü ve sorumluluğunu kendinden saklayarak bir role sığınmasını', ['Birine kasten kötülük etmeyi', 'Yalan söyleyen bir yazarı', 'Siyasi bir komployu'], 'Garson örneğinde olduğu gibi kişi kendini yalnız bir rolden ibaret görünce özgür seçimini inkâr eder; Sartre bunu kötü niyet olarak adlandırır.'),
  ('Anouilh\'nin \'Antigone\' oyununun 1944\'te Paris\'te sahnelenişi neden dikkat çekmiştir?', 'İşgal döneminde otorite ve vicdan çatışmasının farklı biçimlerde yorumlanmasına yol açması', ['İlk kez Latince sahnelenmesi', 'Sessiz film olarak çekilmesi', 'Eserin yasaklanıp yakılması'], 'Antigone\'nin direnişi ile Kreon\'un düzen savunusu, işgal altında hem direnişçilerce hem de rejim yanlılarınca farklı okunmuştur.'),
  ('Giraudoux\'nun \'Truva Savaşı Olmayacak\' oyununun ana kaygısı nedir?', 'Savaşın kaçınılmazlığı karşısında barışı korumaya çalışan aklın yenilgisi', ['Truva\'nın kuruluşu', 'Helen\'in gençliği', 'Tanrıların düğünü'], 'Hektor savaşı önlemek için uğraşır; ancak olaylar onun iyi niyetine rağmen savaşa doğru akar.'),
  ('Jean Genet\'nin \'Hizmetçiler\' oyununda iki kız kardeşin yaptığı oyun nedir?', 'Efendileri olan hanımı öldürmeyi sahneledikleri rol oyunu', ['Bir düğün töreni', 'Bir mahkeme oyunu', 'Sahne dışı bir ev partisi'], 'Solange ve Claire, hanımlarının yokluğunda onun rolünü oynayıp öldürme tören oyununa girişir; gerçeklik ve oyun iç içe geçer.'),
  ('Beckett\'in \'Oyunun Sonu\' (Fin de partie) oyununun kahramanları Hamm ve Clov\'un ilişkisi nasıldır?', 'Tekerlekli sandalyedeki kör Hamm ile ona bağımlı ama ayrılamayan uşağı Clov', ['Baba ile oğul olan iki asker', 'İki kardeş yargıç', 'Evli bir çift'], 'Hamm kör ve yürüyemez; Clov oturamaz. Birbirlerinden bıkmışlardır ama ayrılamazlar; oyun, tükenişin tekrarını gösterir.'),
  ('Beckett\'in \'Mutlu Günler\' oyununda Winnie\'nin durumu nasıl betimlenir?', 'Sahnede önce beline, sonra boynuna kadar bir tümseğe gömülür', ['Uzun süre uyur', 'Gemiyle yolculuk eder', 'Hasta yatağında konuşur'], 'Winnie her koşulda \'mutlu bir gün\' olduğunu söyler; gömülme, yaşamın çaresizliğini ve alışkanlıkların gücünü simgeler.'),
  ('Antonin Artaud\'nun \'Zulüm Tiyatrosu\' fikri neyi savunur?', 'Seyirciyi şok eden, sözden çok beden, ses ve ritüele dayanan tiyatro', ['Salon komedisi', 'Tarihî olayların sakin anlatımı', 'Yalnız şiir okunan sahne'], 'Artaud, tiyatronun seyirciyi derinden sarsarak bilinçaltını harekete geçirmesi gerektiğini savunmuştur.'),
  ('Perec\'in \'Hayat Kullanım Kılavuzu\' romanının kurgu çerçevesi nedir?', 'Paris\'te bir apartmanın odalarını ve sakinlerinin yaşamlarını bir bulmaca gibi sırayla dolaşan yapı', ['Bir geminin güvertesi', 'Bir savaşın cepheleri', 'Bir köyün dört mevsimi'], '1978 tarihli roman, satranç atının hareketi gibi bir kurala göre apartmanın odalarını anlatır; Oulipo anlayışının büyük örneğidir.'),
  ('Aimé Césaire\'in \'Memleketime Dönüş Defteri\' hangi düşünsel akımın temel metinlerindendir?', 'Zenci kimliğini ve Afrika kültürünü savunan négritude akımının', ['Dada akımının', 'Sembolizmin', 'Parnasçılığın'], 'Martinikli şair Césaire, sömürgecilik eleştirisini ve kara kimliğin onurunu şiirsel bir coşkuyla dile getirir.'),
  ('Chaucer, Westminster Abbey\'de gömülmesiyle hangi alanda bir \'ilk\'e imza atmıştır?', 'Poets\' Corner\'a gömülen ilk şair olması', ['Kral mezarlığına gömülen ilk yazar olması', 'Katedrale gömülen ilk gezgin olması', 'İngiltere\'nin ilk ulusal mezarlığına gömülmesi'], 'Chaucer, 1400\'de ölünce Westminster Abbey\'e gömüldü; bu yer sonraları \'Şairler Köşesi\' olarak anıldı.'),
  ('Langland\'ın \'Piers Plowman\' adlı uzun şiiri hangi türün örneğidir?', 'Rüya biçiminde kurgulanmış alegorik bir anlatı', ['Aşk şarkılarından oluşan bir şiir dizisi', 'Kahramanlık anlatan, yer adlarıyla dolu bir destan', 'Krallığın yıllıklarını tutan tarihî kronik'], 'Şair, bir rüya içinde İngiliz toplumunu ve dinî hayatı alegorik kişilerle anlatır; aliteratif dizelerle yazılmıştır.'),
  ('Spenser\'ın şiirinde kullandığı ve kendi adıyla anılan kıta biçimi nasıl bir yapıya sahiptir?', 'Dokuz dizelik, ababbcbcc uyaklı kıta', ['On dört dizelik, tek parça sone biçimi', 'Üç dizelik, zincirleme uyaklı terza rima', 'Dört dizelik, halk türküsü kıtası'], 'Spenser kıtası, ababbcbcc kafiye düzenine sahiptir; son dize altı vurguludur (aleksandren).'),
  ('Sidney\'in \'Şiirin Savunması\' (Defence of Poesy) adlı eserinin temel savı nedir?', 'Şiirin ahlaken yükseltici ve öğretici olması', ['Şiirin tarihe göre güvenilmez olması', 'Şiirin tiyatrodan daha zararlı olması', 'Şiirin yalnız soylulara özgü olması'], 'Sidney, şiirin tarih ve felsefeden daha güçlü bir öğretici etki yaptığını savunarak Puritan eleştirilere yanıt verir.'),
  ('Marlowe\'un \'Malta Yahudisi\' oyununun başkarakteri hangisidir?', 'Barabas', ['Shylock, Venedik tüccarı', 'Fagin, hırsız çetesi başı', 'Volpone, Venedik soylusu'], 'Barabas, Marlowe\'un trajik-komik oyununda intikamcı bir tüccardır; sonraki Shylock tipine öncü sayılır.'),
  ('Jonson\'ın \'mizaç komedisi\' (comedy of humours) anlayışı neye dayanır?', 'Her kişinin tek baskın huyla abartılması', ['Tanrıların oyuna karışıp olayları çözmesi', 'Yalnızca ağıt biçimli şiirlerin kullanılması', 'Sahnede hiç diyalog bulunmaması'], 'Eski tıp anlayışındaki dört \'mizaç\'tan esinlenen Jonson, karakterlerini baskın huylarıyla gülünç hâle getirir.'),
  ('Wyatt ve Surrey\'nin İngiliz şiirine en önemli katkısı hangisidir?', 'Sone biçimini İngilizceye aktarmaları', ['Destan biçimini sahneden kaldırmaları', 'Halk baladını yasaklamaları', 'Oyunlar için ilk sahneyi kurmaları'], 'Thomas Wyatt Petrarca sonesini İngilizceye çevirdi; Surrey ise İngiliz sone biçimini ve blank verse\'ü geliştirdi.'),
  ('Elizabeth döneminde Shakespeare\'in de yer aldığı topluluğun adı nedir?', 'Lord Chamberlain\'s Men', ['Royal Shakespeare Company', 'Lord Admiral\'s Men', 'Queen Anne\'s Men'], 'Shakespeare\'in oyuncu ve oyun yazarı olarak bağlı olduğu topluluk, sonra \'King\'s Men\' adını aldı.'),
  ('Macbeth\'te \'kadından doğmamış hiç kimse sana zarar veremez\' kehanetinin gerçeklesmesi nasıl olur?', 'Macduff\'ın annesinin karnı yarılarak doğmuş olması', ['Macbeth\'in kendi eliyle surların üstünden düşmesi', 'Macbeth\'in kendi kılıcı üstüne düşüp kendini yaralayarak ölmesi', 'Banquo\'nun hayaletinin saldırması'], 'Macduff, ana rahminden vaktinden önce alınmıştır; bu yüzden Macbeth\'i yenmesi kehanete aykırı olmaz.'),
  ('Hamlet\'te Laertes ile Hamlet\'in düellosunun sonunda kimler ölür?', 'Gertrude, Claudius, Laertes ve Hamlet', ['Yalnızca Hamlet ile Claudius ölür', 'Yalnızca Hamlet ile Laertes ölür', 'Ophelia ve Horatio'], 'Zehirli kılıç ve zehirli kadeh yüzünden önce Gertrude, ardından Laertes, Claudius ve Hamlet ölür.'),
  ('Fırtına\'da Caliban\'ın Prospero\'ya yönelik şikâyeti nedir?', 'Prospero\'nun kendi adasını elinden alıp onu köle yapması', ['Prospero\'nun onu zorla şehre götürmeye çalışması', 'Prospero\'nun onu adadan kovup sürgüne göndermesi', 'Prospero\'nun ona okuma öğretmemesi'], 'Caliban, adanın eski sahibi olduğunu söyler; oyun sömürgecilik okumalarına da kaynaklık eder.'),
  ('Shakespeare\'in kısa süreli tiyatro kapanışları sırasında yazdığı \'Venüs ve Adonis\' ve \'Lucrece\'in Kaçırılışı\' hangi türdedir?', 'Uzun anlatı şiiri', ['Komedi biçiminde yazılmış bir sahne oyunu', 'Tarihî oyun', 'Pastoral drama'], '1592-94\'te veba nedeniyle tiyatrolar kapanınca Shakespeare bu iki uzun şiiri yazıp bir soylu koruyucuya ithaf etmiştir.'),
  ('Shakespeare\'in küçük oğlu Hamnet hangi yıl öldü ve bu olay Hamlet ile ilişkilendirilir?', '1596, oğlunun adı Hamlet\'e benzediği için', ['1580, kızının adı Ophelia\'ya benzediği için', '1616, babasının adı aynı olduğu için', '1599, Globe\'un açılışı için'], 'Eleştirmenler Hamnet\'in ölümüyle 1600 dolaylarında yazılan Hamlet arasında bağ kurar; ancak bu yorum kesin bir kanıta dayanmaz.'),
  ('Milton\'ın \'Lycidas\' şiirinin türü nedir?', 'Genç bir arkadaşın ölümü için yazılan pastoral ağıt', ['Şövalyelerin savaşını konu alan uzun bir destan anlatısı', 'Tarihî kronik', 'Mektup biçimli aşk şiiri'], 'Edward King\'in boğularak ölümü üzerine yazılan şiir, çoban kılığındaki ağıtla zamanın akışı ve ölüm üzerine düşünür.'),
  ('Donne\'un \'Ayrılığa Veda: Yas Tutmayı Yasaklayan\' şiirinde birbirinden ayrılan âşıkları anlatan benzetme nedir?', 'Pergelin iki ayağı', ['Bir geminin iki demir çapası, birbirine zincirle bağlı', 'Güneş ve ay', 'İki ırmak'], 'Bir ayak yerinde sabit kalırken diğeri dönüp onun çevresinde dolaşır; bu \'conceit\', metafizik şiirin ünlü örneğidir.'),
  ('\'Gül tomurcuklarını açılırken topla\' (Gather ye rosebuds) dizesiyle tanınan Cavalier şair kimdir?', 'Robert Herrick', ['Richard Lovelace', 'John Suckling', 'George Herbert'], 'Herrick\'in \'Bakireler için\' şiiri, gençliğin geçiciliğini ve anı yaşama düşüncesini işleyen Cavalier şiirinin özetidir.'),
  ('William Congreve\'in \'Dünyanın Yolu\' (The Way of the World) komedisinde Mirabell ile aşk ilişkisi yaşayan kadın kimdir?', 'Millamant', ['Marwood', 'Lady Bracknell', 'Beatrice'], 'Millamant, zeki ve bağımsız ruhlu kadın tipidir; evlilik öncesi koşulları sıraladığı sahne ünlüdür.'),
  ('Goldsmith\'in \'Eğilerek Fethetmek\' (She Stoops to Conquer) komedisinde yaşanan kargaşa neye dayanır?', 'Genç adamın evi han sanıp ev sahibine hakaret etmesi', ['İki kardeşin aynı kadına âşık olup birbirleriyle bozuşmaları sonucu karışıklık çıkması', 'Kralın kılık değiştirmesi', 'Bir hazinenin kaybolması'], 'Marlow, Hardcastle evini han sanır; yanlış anlaşılma komedi kaynağıdır.'),
  ('Henry Fielding\'in \'Joseph Andrews\' romanı, hangi eserin ahlak anlayışına karşı yazılmış bir parodi olarak başlamıştır?', 'Pamela', ['Robinson Crusoe', 'Gulliver\'in Gezileri', 'Clarissa\'nın kuzeni'], 'Fielding, Richardson\'ın Pamela\'sındaki erdem anlayışını alaya almak üzere Pamela\'nın kardeşi Joseph\'in öyküsünü yazmıştır.'),
  ('Laurence Sterne\'ün \'Tristram Shandy\' romanını alışılmış romandan ayıran özellik hangisidir?', 'Sürekli konudan sapmalar, kronolojik düzenin bozulması ve görsel oyunlar', ['Tek bir günün olaylarının sıralı ve düzenli biçimde, hiç sapmadan ayrıntılı anlatılması', 'Yalnızca diyaloglardan oluşması', 'Manzum anlatı biçimi'], 'Anlatıcı kendi doğumuna bile geç gelir; siyah sayfa ve boş sayfa gibi tipografik oyunlar roman geleneğiyle alay eder.'),
  ('Ann Radcliffe\'in \'Udolpho\'nun Gizemleri\' romanında doğaüstü görünen olayların sonunda nasıl bir açıklaması vardır?', 'Mantıklı ve doğal nedenlerle açıklanır', ['Hayaletlerin gerçekten var olduğunun ortaya çıkmasıyla birlikte', 'Şatonun sahibinin gerçekten büyücü olduğu anlaşılır', 'Olayların tümü kahramanın rüyası çıkar'], 'Radcliffe, ürkütücü olayları sonunda akılcı açıklamalara bağlar; buna \'açıklanmış doğaüstü\' denir.'),
  ('Matthew Lewis\'in \'Keşiş\' romanının Radcliffe\'ten farkı nedir?', 'Daha karanlık, şiddetli ve gerçek doğaüstü öğelerle yazılmış olması', ['Daha neşeli, tamamen gerçekçi ve hiç doğaüstü öğe içermeyen bir komedi türünde yazılmış olması', 'Çocuklar için yazılmış bir masal olması', 'Manzum yazılması'], '\'The Monk\', dönemin sansürcülerini rahatsız eden cinsellik ve şiddet unsurlarıyla Gotik romanın aşırı koludur.'),
  ('Gulliver\'in Gezileri\'nde uçan bir ada ve bilim insanlarını hicveden bölüm hangi ülkeyle ilgilidir?', 'Laputa', ['Lilliput', 'Brobdingnag', 'Blefuscu'], 'Laputa, gerçeklikten kopuk akademisyenleri ve soyut bilimi alaya alır.'),
  ('Fanny Burney\'nin \'Evelina\' romanı hangi türün öncü örneğidir?', 'Genç bir kızın toplumla ilk karşılaşmasını anlatan görgü romanı', ['Savaş sırasında cepheye giden askerin psikolojik çöküşünü ve bunalımını işleyen roman', 'Polisiye roman', 'Tarihî roman'], 'Evelina, toplum yaşamına ilk adım atan genç kızın hatalarını ve görgü kurallarını mektuplarla anlatır.'),
  ('Austen\'ın romanlarında sıkça kullanılan \'serbest dolaylı anlatım\' tekniği neyi sağlar?', 'Anlatıcının sesiyle kahramanın düşüncesinin kesintisiz karışmasını', ['Her olayın yalnızca diyalog yoluyla, anlatıcı hiç araya girmeden, düz biçimde verilmesini', 'Anlatıcının hiç görünmemesini', 'Şiirsel ağıtların eklenmesini'], 'Teknik, kahramanın bakış açısının yazarın ironisiyle iç içe geçmesini sağlar.'),
  ('Mary Shelley\'nin ailesi bakımından hangi iki ünlü düşünürün kızıdır?', 'Mary Wollstonecraft ve William Godwin', ['Edmund Burke ve Mary Astell, siyaset yazarları', 'Thomas Paine ve Hannah More', 'Daniel Defoe ve Aphra Behn'], 'Annesi feminist düşünür Mary Wollstonecraft, babası filozof William Godwin\'dir.'),
  ('Anne Brontë\'nin \'Wildfell Hall\'ın Kiracısı\' romanı hangi tutumuyla cesur sayıldı?', 'Alkolik kocasını terk eden bir kadının kendi geçimini sağlaması', ['Savaş sırasında cepheden dönen subayın zenginleşmesini ve toplumda yükselmesini işlemesi', 'Bir kralın hicvedilmesi', 'Doğaüstü olaylar işlenmesi'], 'Helen Graham\'ın evlilikten ayrılması, dönemin ahlak anlayışına meydan okuyan bir tutumdu.'),
  ('Dickens\'ın \'Küçük Dorrit\' romanında Dorrit ailesinin babası hangi yerde uzun yıllar yaşamıştır?', 'Marshalsea borçlular hapishanesinde', ['Newgate cezaevinde', 'Dotheboys Hall okulunda', 'Bethlem Hastanesi\'nde'], 'Dickens\'ın babası da borç yüzünden Marshalsea\'ya girmişti; yazar bu deneyimini romanına yansıtmıştır.'),
  ('Dickens\'ın çocukluğunda babasının hapse girmesi üzerine çalışmak zorunda kaldığı yer neresidir?', 'Bir cila (boya) fabrikası', ['Bir madeni kömür ocağı', 'Bir gemi tersanesi', 'Bir matbaa'], 'Dickens on iki yaşında Warren\'s Blacking fabrikasında çalıştı; bu aşağılanma duygusu yazılarında sürekli yankılanır.'),
  ('Dickens\'ın \'Nicholas Nickleby\' romanında eleştirilen kurum hangisidir?', 'Yorkshire\'daki kötü yatılı okullar', ['Parlamento', 'Donanma', 'Kilise'], 'Dotheboys Hall\'daki Bay Squeers, çocukları aç bırakıp döven sahtekâr bir müdürdür; roman bu tür okulların kapanmasına katkıda bulunmuştur.'),
  ('Dickens\'ın \'Boz\' takma adı hangi eserle birlikte ünlendi?', 'Boz\'un Taslakları', ['Kasvetli Ev', 'Çanlar', 'Gizemli Dost'], 'Dickens, ilk yazılarını gazetelere bu takma adla yazdı ve daha sonra kitap olarak yayımladı.'),
  ('Vanity Fair adı hangi eserden alınmıştır?', 'Bunyan\'ın \'Hacı\'nın Yolculuğu\'ndan', ['Milton\'ın \'Kaybolmuş Cennet\'inden', 'Shakespeare\'in \'Hamlet\'inden', 'Defoe\'nun \'Robinson Crusoe\'sundan'], 'Bunyan\'ın alegorisinde \'Vanity Fair\', dünyevi çıkar ve boş gösterişlerin panayırıdır.'),
  ('Anthony Trollope\'un \'Barsetshire Günlükleri\' dizisinde işlenen çevre nedir?', 'İngiliz taşra kilisesi ve din adamlarının yaşamı', ['Londra\'daki bankacılar', 'Askeri akademi', 'Sömürge yöneticileri'], 'Trollope, kurgusal Barsetshire\'da din adamlarının mevki hırslarını ve küçük kasaba yaşamını sakin bir ironiyle anlatır.'),
  ('Gerard Manley Hopkins\'in şiirini yenilikçi yapan \'sıçrayan ritim\' (sprung rhythm) neye dayanır?', 'Hece sayısına değil, vurgulu hecelerin sayısına', ['Sabit sayıda hece sayısına', 'Yalnızca uyağa', 'Sessiz harflere'], 'Hopkins, konuşma dilinin vurgusunu şiire taşıdı; eserleri ölümünden sonra, 1918\'de yayımlandı.'),
  ('Christina Rossetti\'nin \'Goblin Çarşısı\' (Goblin Market) şiirinde iki kız kardeşten biri nasıl kurtulur?', 'Kardeşinin cesaretiyle ve fedakârlığıyla', ['Bir büyücünün yardımıyla', 'Kralın emriyle', 'Bir gemiyle kaçarak'], 'Lizzie, cinlerin meyvelerini yemeyi reddedip kardeşini kurtarır; şiir ahlaki ve cinsel temaların iç içe geçtiği bir masal-alegoridir.'),
  ('Shaw\'un \'Binbaşı Barbara\' oyununun başlıca çatışması nedir?', 'Kurtuluş Ordusu ile silah fabrikatörü babanın dünya görüşü çatışması', ['Askerî kışlada bir isyan', 'İki kız kardeşin miras kavgası', 'Bir doktorun hatası'], 'Barbara\'nın idealizmi, silah yapımcısı babası Undershaft\'ın para ve güç anlayışıyla karşılaşır.'),
  ('Shaw\'un siyasal olarak yer aldığı Fabian Derneği hangi görüşü savunur?', 'Yavaş ve yasal yollarla sosyalizme ulaşmayı', ['Silahlı devrimle işçi sınıfının iktidarı ele geçirmesini', 'Mutlak monarşiyi', 'Serbest piyasayı'], 'Fabian Derneği, Shaw ve Wells gibi aydınların da katıldığı, reformcu sosyalist bir örgüttür.'),
  ('Kipling\'in \'Kim\' romanında genç kahramanın yaşadığı dünya hangisidir?', 'Hindistan\'da İngiliz casuslarla yerlilerin yolları kesiştiği Büyük Oyun', ['Afrika\'daki altın madenlerinde sömürge memurlarıyla yerlilerin çatıştığı dünya', 'Avustralya sürgün kolonisi', 'Kuzey Amerika kürk ticareti'], 'Yetim İngiliz çocuğu Kim, Hindistan\'ın sokaklarında büyür ve Büyük Oyun denen casusluk mücadelesine karışır.'),
  ('Stevenson\'ın \'Kaçırılmış\' (Kidnapped) romanında David Balfour\'un yolculuk arkadaşı kimdir?', 'İskoçyalı Alan Breck', ['İskoçyalı Long John Silver, korsan aşçı', 'Jim Hawkins', 'Ben Gunn'], 'David, amcası tarafından kaçırılır; İskoç dağlarında Jacobite savaşçı Alan Breck ile birlikte yol alır.'),
  ('Yeats\'in \'Paskalya, 1916\' şiirinin ünlü ifadesi \'Korkunç bir güzellik doğdu\' neyi anlatır?', 'İrlanda Paskalya Ayaklanması\'nın yarattığı sarsıcı dönüşümü', ['İrlanda ile İngiltere arasındaki barış anlaşmasının getirdiği sakin ve mutlu ortamı', 'Bir doğum günü kutlamasını', 'Bir kralın taç giymesini'], 'Şiir, ayaklanma lideri olan ve idam edilen tanıdıkları üzerinden ulusal bir dönüşümü ve ahlaki karmaşayı işler.'),
  ('Synge\'in \'Batı Dünyasının Şehzadesi\' oyunu 1907\'de Abbey Tiyatrosu\'nda neden olay çıkardı?', 'Köylünün babasını öldürdüğünü anlatmasının alkışlanması', ['Baş oyuncunun sahnede rahatsızlanması', 'Oyunun kraliyet ailesini alaya alması', 'Oyunun kadınlara yasaklanması'], 'Seyirciler, İrlanda\'yı kaba ve cinayeti öven bir topluluk gibi gösterdiği gerekçesiyle protesto etti.'),
  ('Sean O\'Casey\'in \'Juno ve Tavus Kuşu\' oyunu hangi dönemde geçer?', 'İrlanda İç Savaşı dönemi', ['Napolyon Savaşları\'nın bitişini izleyen yıllar', 'Orta Çağ', 'Viktorya dönemi'], 'Dublin\'deki yoksul bir ailenin yıkımı üzerinden oyun, şiddet ve yoksulluk altında ezilen insanları anlatır.'),
  ('Joyce\'un \'Finnegans Wake\' eserinin dilsel özelliği nedir?', 'Çok dilli sözcük oyunlarıyla örülü, olağanüstü karmaşık bir dil', ['Tek ve sade bir dille yazılmış, çocuklara hitap eden ve kolay okunur bir anlatı biçimi', 'Çocuk diliyle yazılmış yalın bir üslup', 'Şiirli bir tarih kroniği'], 'Joyce, birçok dilden sözcüğü karıştırarak kendi dilini oluşturdu; cümle ortasında başlayıp biten döngüsel bir yapıya sahiptir.'),
  ('Virginia Woolf\'un \'Deniz Feneri\'ne\' (To the Lighthouse) romanında zamanın akışı nasıl işlenir?', 'Tek bir akşam ile yıllar sonraki dönüşü kapsayan üç bölümle, bilinç akışı aracılığıyla', ['Tek bir günün saatleri boyunca, yalnızca diyaloglarla ve olay sırasına bağlı kalarak, Londra sokaklarında', 'Mektuplarla yıllar boyu', 'Kronik biçimli yıllıklarla'], 'Roman, Ramsay ailesinin yazlık evindeki bir akşamı, ardından savaş yıllarını ve fenere gidişi anlatır; zaman iç dünyanın aynasında verilir.'),
  ('Katherine Mansfield\'in \'Bahçe Partisi\' öyküsünde Laura\'nın partiden sonra yaşadığı değişim nedir?', 'Yoksul komşunun ölümüyle yaşamın acılığını ilk kez kavraması', ['Zengin bir damat bulması', 'Parti için aşırı övgü alması', 'Köyü terk etmesi'], 'Laura, parti sürerken bir işçinin ölümüne tanık olur; yaşam ve ölümün bir arada oluşunu sezer.'),
  ('Eliot\'ın \'Dört Kuartet\' hangi temayı ele alır?', 'Zaman, bellek, ruhsal kavrayış ve ölümsüzlük arayışını', ['Savaş cephelerinin acımasız tablosunu ve askerlerin siper yaşamının ayrıntılarını anlatmayı', 'Şehir yaşamının komedisini', 'Siyasi liderliği'], 'Dört bölümden oluşan şiir dizisi, \'şimdiki zaman\' ile ebediyet arasındaki ilişkiyi felsefi bir dille işler.'),
  ('Siegfried Sassoon ile Wilfred Owen\'ın tanıştığı yer neresidir?', 'Craiglockhart askerî hastanesi', ['Gelibolu siperleri ve cephedeki küçük ve sert bir revir', 'Oxford Üniversitesi', 'Londra\'daki kulüp'], 'Bu hastane, savaş travmasına bağlı sinir bunalımı geçiren subayların tedavi gördüğü yerdi; Owen burada şiirini geliştirdi.'),
  ('Auden\'in \'Musée des Beaux Arts\' şiirinde bir tabloyla ilgili vurguladığı düşünce nedir?', 'Trajik olayların insanlar tarafından fark edilmeden olağan yaşamın içinde gerçekleştiği', ['Sanatın gücünün savaşı durdurabildiği ve dünyayı değiştirebildiği, ressamların toplumu yönlendirdiği fikri', 'Ressamların yoksul olduğu', 'Müzelerin kapatılması gerektiği'], 'Şiirde Bruegel\'in \'İkarus\'un Düşüşü\' tablosu, dünyanın başkasının acısına kayıtsızlığını gösterir.'),
  ('Evelyn Waugh\'un \'Brideshead\'e Dönüş\' romanında anlatıcı Charles Ryder\'ın ilişkisi nasıl bir aileyle kurulur?', 'Katolik, aristokrat Flyte ailesiyle', ['Protestan, orta sınıftan işçi bir aileyle, kentin sanayi bölgesinde', 'Bir kraliyet ailesiyle', 'Bir göçmen aileyle'], 'Roman, nostaljik bir bakışla İngiliz aristokrasisinin çöküşünü ve inanç temasını işler.'),
  ('Graham Greene\'in \'Gücün ve Görkemin\' romanında \'viski rahibi\' neden kaçak yaşar?', 'Meksika\'da dinin yasaklandığı bir dönemde rahiplik yapmasından dolayı', ['Meksika\'da bir kumar borcu yüzünden ve bir polis müfettişinden kaçmak zorunda kalmasından dolayı', 'Siyasi bir muhalif olduğu için', 'Bir casus olduğu için'], 'Kusurlu bir rahip, ölüm tehlikesine karşın görevini sürdürür; roman inanç ve günah temalarını işler.'),
  ('Anthony Burgess\'in \'Otomatik Portakal\' romanında genç Alex\'in kullandığı özel argo nasıl adlandırılır?', 'Nadsat', ['Newspeak', 'Polari', 'Cockney'], 'Nadsat, İngilizce ile Rusça kökenli sözcüklerin karışımıdır; roman şiddet, özgür irade ve devlet müdahalesini sorgular.'),
  ('Wordsworth\'ün \'Nergisler\' (I Wandered Lonely as a Cloud) şiirine esin kaynağı olan kişi kimdir?', 'Kız kardeşi Dorothy\'nin günlüğü', ['Eşi Mary\'nin mektubu', 'Arkadaşı Coleridge\'in şiiri', 'Kralın emri'], 'Dorothy Wordsworth, nergis tarlasını kaydettiği günlükte anlatmıştı; şiir bu gözlemden doğdu.'),
  ('Blake\'in \'Cennetle Cehennemin Evliliği\' eserinde yer alan \'Cehennem Atasözleri\' neyi hedefler?', 'Geleneksel ahlakın ve dinî ikiliklerin sorgulanmasını', ['Savaşın sonunu ve barışın müjdelenmesini, kralın zaferlerinin övülmesi biçiminde', 'Savaş stratejilerini', 'Seyahat öğütlerini'], 'Blake, karşıtların birliğini savunur; \'coşkunun yolu bilgelik sarayına çıkar\' gibi sözleri geleneksel öğretilere meydan okur.'),
  ('Shelley\'nin \'Şiirin Savunması\'nda şairler için kullandığı ünlü ifade nedir?', 'Dünyanın tanınmamış yasa koyucuları', ['Kralların gizli danışmanları ve saray şairleri, ödüllendirilmiş', 'Halkın düşmanları', 'Tarihin yazıcıları'], 'Shelley, şairlerin insanlığın ahlaki ve toplumsal düşüncesini şekillendiren görünmez yasa koyucular olduğunu söyler.'),
  ('Byron\'ın kızı Ada Lovelace hangi alanda tarihe geçmiştir?', 'İlk bilgisayar programı kavramını geliştirenlerden biri olarak', ['Denizcilik alanında ilk kadın kaptan olarak', 'Roman yazarlığında', 'Tiyatro yönetmenliği'], 'Ada Lovelace, Charles Babbage\'ın Analitik Makinesi için yazdığı notlarla ilk algoritma örneklerinden birini tanımladı.'),
  ('Keats\'in mezar taşındaki \'Adı suya yazılmış biri burada yatıyor\' sözü neyi yansıtır?', 'Şairin kendi adının unutulacağı yönündeki karamsarlığını', ['Şairin adının yayıncı tarafından silinmiş olmasının yarattığı küskünlüğü ve yasak tepkisini', 'Adının yasaklandığını', 'Evlenmediğini'], 'Keats ölürken şöhret kazanamadığını düşündü; sonradan en büyük romantik şairler arasında sayıldı.'),
  ('Harold Pinter\'ın \'Doğum Günü Partisi\' oyununda Stanley\'nin yaşadığı durum nedir?', 'Gizemli iki ziyaretçi tarafından sorgulanıp yıkılması', ['Köydeki düğün hazırlıklarının ve davetlilerin karışıklığın arasında kaybolup hazırlıksız kalması', 'Bir hazine bulması', 'Bir adadan kurtulması'], 'Goldberg ile McCann, nedenini açıklamadan Stanley\'yi baskı altına alır; oyun tehdit ve belirsizlik duygusuyla bilinir.'),
  ('Doris Lessing\'in \'Altın Defter\' romanının temel konusu nedir?', 'Bir kadın yazarın kimliğinin farklı renkteki defterlere bölünmesi ve parçalanma yaşaması', ['Bir kadın yazarın kayıp mektuplar bularak sahte kimliğe bürünüp başka bir ülkede yeni yaşam kurması', 'Sömürge yöneticisi', 'Taşra evliliği'], 'Anna Wulf, yaşamını dört ayrı defterde tutar; roman kadın deneyimi, siyaset ve yazarlık bunalımını işler.'),
  ('Iris Murdoch\'un romanlarında en sık işlenen konu hangisidir?', 'Aşk, iyilik, ahlaki seçim ve insan ilişkilerinin karmaşıklığı', ['Yer altı kentlerinde geçen uzun bir uzay yolculuğu ve bilimkurgu serüvenleri', 'Seri cinayet', 'Orta Çağ savaşları'], 'Murdoch, felsefeci kimliğiyle de, romanlarında özgür irade ve iyilik üzerine düşünür.'),
  ('Ishiguro\'nun \'Beni Asla Bırakma\' (Never Let Me Go) romanında Hailsham öğrencilerinin gizli kaderi nedir?', 'Organ bağışı için yetiştirilen klonlar olmaları', ['Savaş kahramanı olacak çocuklar olmaları', 'Casus yetiştirilmesi', 'Uzay yolcusu seçilmesi'], 'Kathy ve arkadaşları, kendi kaderlerini sorgusuz kabullenir; roman insan olmanın anlamını ve sınırlarını sorar.'),
  ('Racine\'in tragedyalarıyla Corneille\'inkiler arasındaki temel fark hangisidir?', 'Racine tutku ve iç çatışmayı, Corneille irade ve onuru öne çıkarır', ['Racine komedi, Corneille tragedya yazar', 'Racine Latince, Corneille Fransızca yazar', 'Racine nesir, Corneille şiir yazar'], 'Corneille\'in kahramanları iradeleriyle seçim yapar; Racine\'in kahramanları tutkularının tutsağı olur.'),
  ('Bossuet\'nin ünlü \'Cenaze Konuşmaları\' hangi türün klasik örnekleridir?', 'Ölen soylular için yazılmış belâgat (hitabet) metinleri', ['Aşk mektupları', 'Seyahat anlatıları', 'Şövalye romansları'], 'Bossuet, XVII. yüzyılın büyük hatibi olarak, kraliyet ailesinin üyeleri için görkemli cenaze konuşmaları yazdı.'),
  ('Marie de France\'ın \'Lai\' adlı kısa anlatı şiirleri hangi konu etrafında döner?', 'Çoğunlukla aşk ve doğaüstü öğeler içeren Kelt kökenli şövalye hikâyeleri', ['Hukuk davaları', 'Haçlı seferlerinin bilançosu', 'Köylü ayaklanmaları'], 'Marie, 12. yüzyılda Anglo-Norman dilinde yazdığı lai\'lerle ilk kadın şairlerden sayılır.'),
  ('Clément Marot\'un Fransız edebiyatındaki önemi nedir?', 'Kral I. François\'nın sarayında zarif, hafif ve doğal şiir yazması ve Mezmurları çevirmesi', ['Tiyatro oyunları yazması', 'Roman türünü başlatması', 'Latince şiir geleneğini yaşatması'], 'Marot, Rönesans şiirinde zarif üslup ve epigramlarla tanındı; dinî görüşleri nedeniyle sürgüne gitmek zorunda kaldı.'),
  ('Du Bellay\'in \'Pişmanlıklar\' (Les Regrets) şiir dizisi hangi duyguyu yansıtır?', 'Roma\'da geçirdiği yıllarda duyduğu memleket özlemini ve hayal kırıklığını', ['Savaş zaferinin coşkusunu', 'Taşra yaşamının huzurunu', 'Genç aşkın coşkusunu'], 'Du Bellay, Roma\'ya gittiği yıllarda Fransa\'ya duyduğu özlemi, \'Mutlu olan Ulysses\' sonesiyle de dile getirdi.'),
  ('Marguerite de Navarre\'ın \'Heptaméron\' adlı eseri hangi eserin Fransız karşılığı sayılır?', 'Boccaccio\'nun Decameron\'unun', ['Chaucer\'ın Canterbury Hikâyeleri\'nin', 'Dante\'nin İlahi Komedya\'sının', 'Cervantes\'in Don Kişot\'unun'], 'Yedinci güne kadar anlatılan hikâyeler, seller yüzünden bir manastırda mahsur kalan kişilerin sohbetlerinden oluşur.'),
  ('Mme de Lafayette\'in \'Clèves Prensesi\' romanında Prenses\'in kocasına yaptığı şaşırtıcı itiraf nedir?', 'Başka bir erkeğe karşı duyduğu aşkı kocasına söylemesi', ['Servetini kaybettiğini söylemesi', 'Ailesinin sırrını açıklaması', 'Saraydan kaçmak istediğini söylemesi'], 'Prenses, sadık kalma çabasında kocasına duygusunu açıkça söyler; bu itiraf romanın dönüm noktasıdır.'),
  ('Andrey Bely\'nin \'Petersburg\' romanının ayırt edici özelliği nedir?', 'Şehrin ve bilincin sembolist, parçalı ve ritmik bir dille anlatılması', ['Tarihî olayların kronolojik anlatılması', 'Mektuplardan oluşması', 'Köy yaşamının betimlenmesi'], 'Bely\'nin romanı, 1905 Devrimi dönemindeki bir suikast planını sembolizm ve deneysel yazıyla işler; Rus modernizminin zirvelerindendir.'),
  ('Vasili Grossman\'ın \'Hayat ve Kader\' romanı hangi tarihî olay çevresinde geçer?', 'Stalingrad Muharebesi ve Sovyet toplumunun baskı düzeni', ['Napolyon\'un Rusya seferi', 'Kırım Savaşı', '1905 Devrimi'], 'Roman, savaşı ve Stalin dönemini birlikte inceler; Sovyet yönetimince yasaklanmış, yıllar sonra yayımlanmıştır.'),
  ('Zhukovski\'nin Rus edebiyatındaki yeri nedir?', 'Alman ve İngiliz romantik şiirlerini çevirerek Rus romantizminin yolunu açması', ['İlk Rus romanını yazması', 'Çar\'ın sansür başkanı olması', 'Tiyatro eleştirmeni olması'], 'Zhukovski, Schiller ve Byron gibi şairlerin çevirileriyle Rus şiirinin ifade gücünü artırdı; genç Puşkin\'in hocası sayılır.'),
  ('Fet ve Tyutçev gibi şairlerin Rus edebiyatındaki ortak özelliği nedir?', 'Toplumsal tartışmalardan uzak, doğa ve duyguya yönelen lirik şiir yazmaları', ['Siyasi hiciv yazmaları', 'Roman ağırlıklı çalışmaları', 'Tiyatro yönetmenliği'], 'Bu şairler, \'sanat için sanat\' eğilimiyle doğa ve içsel duygulara yönelmişlerdir.'),
  ('Mihail Lomonosov\'un Rus edebiyatındaki önemi nedir?', 'Rus yazı dilinin kurallarını ve şiir ölçüsünü düzenlemesi', ['İlk romanı yazması', 'Tiyatro binası yaptırması', 'Halk masallarını derlemesi'], 'Lomonosov, Rusça dilbilgisi ve üslup kuramlarıyla Rus yazı dilinin gelişimine büyük katkıda bulundu.'),
  ('Derjavin\'in \'Felitsa\' ode\'sinin dikkat çeken özelliği nedir?', 'Kraliçe II. Katerina\'ya övgü içinde, esprili ve gündelik bir dille yazılmış olması', ['Tamamen Latince olması', 'Kralı sert eleştirmesi', 'Halk ayaklanmasını övmesi'], 'Derjavin, ağırbaşlı ode geleneğini günlük dil ve mizahla yumuşatarak yeni bir ton getirdi.'),
  ('Ted Hughes\'un \'Karga\' (Crow) şiir dizisinin ana figürü nasıl bir varlıktır?', 'Yaratılışın ve şiddetin karşısında cüretkâr, alaycı bir karga', ['Kimseye boyun eğmeyen, savaşları yöneten, yaratılışa hiç meydan okumayan sadık bir tilki', 'Sadık bir köpek', 'Barış güvercini'], 'Hughes, mitolojik ve vahşi bir imge dünyasında Karga\'yı Tanrı\'ya meydan okuyan bir figür olarak kullanır.'),
  ('Romain Rolland\'ın \'Jean-Christophe\' romanının kahramanı kimdir?', 'Alman asıllı bir müzisyen', ['Fransız bir ressam, taşra köylerinin sade manzaralarını çizen sanatçı', 'İtalyan bir heykeltıraş', 'İngiliz bir denizci'], 'Rolland, Beethoven\'ı anımsatan dahi besteci Jean-Christophe\'un yaşamı üzerinden insanlar ve uluslar arası kardeşliği işler.'),
  ('François Mauriac, 1952\'de Nobel Edebiyat Ödülü\'ne hangi niteliğiyle değer görülmüştür?', 'Katolik ahlak ve tutku çatışmalarını işleyen romanlarıyla', ['Yalnızca tarihî olayların anlatılmasını ve kral biyografilerini dile getiren romanlarıyla', 'Bilimkurgu eserleriyle', 'Gezi yazılarıyla'], 'Mauriac, taşra burjuvazisindeki günah, suçluluk ve inanç sorunlarını yoğun psikolojik çözümlemelerle anlatmıştır.'),
  ('Colette\'in \'Chéri\' romanı hangi duyguyu merkeze alır?', 'Yaşlanan bir kadın ile genç sevgilisinin ilişkisini', ['Savaştan dönen bir gazinin bir köy kızına duyduğu ve yıllarca süren umutsuz aşkı', 'Köylü kızın serüvenini', 'Bir dedektifin vakasını'], 'Colette, duygusal inceliklerle dolu bir dille aşkın zamanla sınanışını anlatır.'),
  ('Cocteau\'nun \'Korkunç Çocuklar\' romanı hangi iki kardeşin kapalı dünyasını anlatır?', 'Paul ve Élisabeth\'in', ['Pierre ve Jean\'ın', 'Jacques ve Marie\'nin', 'Alex ve Anna\'nın'], 'Cocteau, dış dünyaya kapalı iki kardeşin oyunlar, rüyalar ve yıkımla dolu ilişkisini işler.'),
  ('Le Clézio\'ya 2008\'de Nobel Edebiyat Ödülü kazandıran yazın anlayışı için hangisi söylenebilir?', 'Sömürge sonrası kimlikler, doğa ve insan arasındaki ilişkiyi işlemesi', ['Tarihî romanlara bağlılığı', 'Polisiye yazarlığı', 'Tiyatro yazarlığı'], 'Le Clézio\'nun eserleri, Fransa dışındaki kültürlere ve doğaya duyulan ilgiyle öne çıkar.'),
  ('Patrick Modiano\'nun romanlarında en sık işlediği tema hangisidir?', 'Bellek, kayıp kimlik ve Nazi işgali yıllarının izleri', ['Uzay yolculukları, gelecek kuşakların kaderi ve bilimkurgu dünyası ağırlıklı anlatıları', 'Haçlı seferleri', 'Köylü hayatı'], 'Modiano, belirsiz geçmişlere ve unutulmaya karşı bir bellek arayışını sade bir üslupla anlatır; 2014\'te Nobel aldı.'),
  ('Saint-John Perse\'in 1960\'da Nobel Edebiyat Ödülü\'nü almasına gerekçe olan şiir anlayışı için ne söylenebilir?', 'Görkemli, geniş soluklu ve tarihî-mitolojik imgelerle yüklü uzun şiirler', ['Kısa, sade aşk şiirleri', 'Halk türküleri', 'Hiciv ve mizah şiirleri'], 'Perse\'in \'Anabase\' gibi şiirleri, göçebe bir kahramanın kuruluş ve fetih imgeleriyle yazılmış epik bir soluk taşır.'),
  ('Francis Ponge\'un \'Nesnelerin Yanında\' (Le parti pris des choses) kitabında şair neyi yapar?', 'Sıradan nesneleri (çakıl, kibrit, portakal) derin bir dikkatle betimleyerek anlatır', ['Savaş sırasında cepheden yazılan mektupları sıralar', 'Aşk şiirleri yazar', 'Tarihî olayları yorumlar'], 'Ponge, gündelik nesnelerin dilini ve doğasını keşfederek şiiri sıradan şeylerin gözlemine yöneltir.'),
  ('Paul Valéry\'nin \'Bay Teste ile Bir Akşam\' eserindeki kahramanın temel özelliği nedir?', 'Zihnin gücüne ve kendi düşüncesini denetlemeye saplanmış, soğukkanlı bir kişi olması', ['Ticaret ve para kazanma tutkusuyla, dünyaya hükmetme hırsıyla, gezginliği seven bir tüccar tipi', 'Gezgin bir tüccar olması', 'Dinî rahip olması'], 'Valéry, bilinç ve düşünce süreçlerinin ustası olan hayalî bir kişi aracılığıyla zihinsel disiplin ideali üzerine düşünür.'),
  ('Baudelaire\'in \'Kötülük Çiçekleri\'nin 1857\'de yayımlanmasından sonra açılan dava, mahkemenin hangi kararıyla sonuçlandı?', 'Altı şiirin kitaptan çıkarılması ve para cezası verilmesi', ['Kitabın tümünün yakılması, yazarın ise yıllarca sürgüne gönderilmesi', 'Şairin sürgün edilmesi', 'Beraat kararı verilmesi'], 'Ahlaka aykırı bulunan altı şiir yasaklandı; yazarın cezası ancak 1949\'da resmen kaldırılabildi.'),
  ('\'Gerçeküstücü\' (surréaliste) sözcüğünü ilk kez kullanan sanatçı kimdir?', 'Guillaume Apollinaire', ['André Breton, 1924\'te manifesto yazan şair', 'Paul Éluard', 'Louis Aragon'], 'Apollinaire, 1917\'de \'Tirésias\'ın Memeleri\' oyununun alt başlığı olarak bu sözcüğü kullandı; Breton ise akımı manifestoyla başlattı.'),
  ('Anatole France\'ın \'Penguenler Adası\' romanı hangi yöntemle yazılmıştır?', 'Fransa tarihini penguenlerin tarihi kılığında hicveden bir parodi olarak', ['Eski Fransız krallarının resmî tarihini sade bir dille anlatan tarih kitabı olarak', 'Eski İzlanda destanlarının çevirisi olarak', 'Bir bilimkurgu yolculuğu olarak'], 'Kitap, bir adada insanlaşan penguenlerin tarihi üzerinden Fransız tarihini ve siyasetini hicveder; yazar 1921\'de Nobel aldı.'),
  ('Beckett\'in \'Molloy\', \'Malone Ölüyor\' ve \'Adlandırılamayan\' yapıtları hangi biçimde bir araya gelir?', 'Roman üçlemesi', ['Tiyatro dörtlemesi', 'Şiir antolojisi', 'Gezi kitabı serisi'], 'Üçleme, kahramanların bedensel ve zihinsel çözülmesini sınırda bir anlatıyla işler; Beckett\'in nesir alanındaki başyapıtı sayılır.'),
  ('Genet\'nin \'Balkon\' oyununun geçtiği mekân hangisidir?', 'Bir genelev', ['Bir saray', 'Bir manastır', 'Bir hastane'], 'Oyun, devrimin sürdüğü kentte bir genelevde müşterilerin yargıç, general, piskopos rollerini oynamalarını anlatarak iktidar ve gösteriyi sorgular.'),
  ('Jacques Prévert\'in \'Barbara\' şiiri hangi olayın gölgesinde yazılmıştır?', 'İkinci Dünya Savaşı\'nın yıkımı ve bombardıman', ['Fransız Devrimi\'nin Terör dönemindeki toplu idamlar ve kıtlık yılları', 'Cezayir ayaklanması', 'Haçlı seferleri'], 'Şair, Brest\'te yağan yağmur altında gördüğü Barbara adlı genç kadını anımsar ve savaşın akıl almaz yıkımını sorgular.'),
  ('Shakespeare\'in \'Kış Masalı\'ndaki ünlü sahne yönergesi \'Çıkar, bir ayı tarafından kovalanarak\' neyi gösterir?', 'Trajik bir ilk yarıdan komik-masalsı bir ikinci yarıya geçişi', ['Savaşın sonunu ve barışın müjdelenişini anlatan, sahne ışıklarının söndürülüşünü simgeleyen geçişten', 'Oyunun sonuna gelindiğini', 'Sahne ışıklarının söndürüldüğünü'], 'Antigonus\'un ayı tarafından kovalandığı an, oyunun gerilimli Sicilya bölümü ile pastoral Bohemya bölümü arasındaki dönüm noktasıdır.'),
  ('Shakespeare\'in \'Ölçüye Ölçü\' (Measure for Measure) oyunu neden \'sorunlu oyun\' (problem play) sayılır?', 'Komedi biçiminde olmasına karşın adalet ve ahlak konularında rahatsız edici sorular sorması', ['Yalnız tarihî olayları işleyen ve hiç komedi öğesi taşımayan, uzun soluklu bir şiir biçiminde yazılması', 'Uzun şiirle yazılması', 'Hiçbir kişinin cezalandırılmaması'], 'Angelo\'nun ikiyüzlü yönetimi ve Isabella\'nın ikilemi, oyunu salt güldürüden çıkarıp ahlaki bir tartışmaya dönüştürür.'),
  ('Shakespeare\'in \'Titus Andronicus\' oyununun dönemin intikam tragedyalarındaki yeri nedir?', 'En kanlı ve şiddet dolu erken tragedyalarından biri olması', ['En çok güldüren, yalnızca hafif komedi öğeleri taşıyan ve tamamen mutlu biten erken oyunlarından biri', 'Son oyunu olması', 'Tek aşk dramı olması'], 'Oyun, kesilen eller, öldürülen çocuklar ve yenilen yemekle sonlanan şiddet sahneleriyle bilinir; Kyd\'in etkisi görülür.'),
  ('Shakespeare\'in \'II. Richard\' ile başlayıp \'V. Henry\' ile biten ikinci tarih oyunu dörtlemesinde (tetralogy) işlenen ana süreç nedir?', 'Meşruiyeti sorgulanan bir tahtın el değiştirmesi ve Prens Hal\'in olgunlaşıp kral olması', ['Fransa\'nın işgal edilmesi, ardından Katolik ve Protestan mezhepleri arasında çıkan uzun din savaşı', 'Kraliçenin ölümü', 'Ortaçağ şövalyelik ideallerinin tamamen yok olması'], 'Dörtleme II. Richard\'ın devrilmesini, IV. Henry\'nin sorunlu iktidarını ve oğlu Hal\'in V. Henry olarak ün kazanmasını anlatır.'),
  ('Samuel Johnson\'ın \'Rasselas\' adlı kısa romanında Habeş prensinin yaşadığı yer ve aradığı şey nedir?', 'Mutlu Vadi\'den kaçıp gerçek mutluluğun nerede olduğunu araması', ['Saraydaki tahtı devralmak için kardeşiyle savaşıp krallığı kendi ordusuyla geri alması', 'Kardeşinden intikam alması', 'Bir kitap yazması'], 'Rasselas, her şeyin sağlandığı vadiden çıkıp dünyada hiçbir yaşam biçiminin tam mutluluk vermediğini görür.'),
  ('Sheridan\'ın \'Dedikodu Okulu\' (The School for Scandal) komedisinde Joseph Surface\'in en belirgin özelliği nedir?', 'Erdemli görünüp gizlice sahtekârlık yapan ikiyüzlü olması', ['Saf, cömert ve her koşulda dürüst olduğunu kanıtlayan, yoksullara yardım eden kardeş', 'Savaş kahramanı olması', 'Dindar bir rahip olması'], 'Joseph, kardeşi Charles\'ın açık hayatına karşılık kibar bir maske takar; ünlü paravan sahnesi onun maskesini düşürür.'),
  ('Francis Bacon\'ın \'Denemeler\'inde \'Okumak insanı doyurur, konuşmak hazırlar, yazmak kesinleştirir\' görüşü neyi vurgular?', 'Bilginin okuma, tartışma ve yazma ile olgunlaştığını', ['Yalnız okumanın yeterli olduğunu, tartışma ve yazının bilgiyi azalttığı', 'Konuşmanın gereksizliğini', 'Yazının yasaklanması gerektiğini'], 'Bacon, kısa ve özlü deneme türüyle öğüt vererek İngiliz düzyazısının gelişmesine katkıda bulundu.'),
  ('Wilde\'ın \'Salome\' oyununun dili ve sahnelenmesiyle ilgili hangisi doğrudur?', 'Fransızca yazıldı ve Londra\'da sahnelenmesi sansür tarafından yasaklandı', ['Latince yazıldı ve Londra\'da yıllarca çok sevilerek ilk yıllarında yüzlerce kez sahnelendi', 'İtalyanca yazıldı ve Roma\'da hiç sahnelenmedi', 'Yalnızca radyoda yayımlandı'], 'Wilde, İncil\'deki hikâyeyi 1891\'de Fransızca yazdı; Lord Chamberlain, İncil kahramanlarının sahnede gösterilmesini yasakladığı için oyun Londra\'da sahnelenemedi.'),
  ('Shaw\'un \'İnsan ve Üstinsan\' oyununda \'Cehennemde Don Juan\' sahnesi neden önemlidir?', 'Oyunun felsefi tartışmalarını içeren uzun bir rüya bölümü olması', ['Oyunun son sahnesinde Tanrı\'nın yargılanmasını konu alan, kısa bir ahlak oyunu bölümü olması', 'Yazarın otobiyografisi olması', 'Tiyatro tarihini anlatması'], 'Rüya bölümünde Don Juan, Şeytan ve diğerleri yaşam gücü, evlilik ve ilerleme üzerine uzun bir tartışma yürütür.'),
  ('E. M. Forster\'ın ölümünden sonra 1971\'de yayımlanan \'Maurice\' romanı hangi konuyu işler?', 'Eşcinsel bir aşk ve toplumsal baskı', ['Savaş sırasında yaşanan gizli bir casusluk komplosu ve bir askerin sınanışı', 'Denizcilik serüvenini', 'Bir dedektif vakasını'], 'Forster, romanı 1914\'te yazmış ama yasal ve toplumsal tepkiler yüzünden ölümünden sonra yayımlatmıştı.'),
  ('Virginia Woolf\'un \'Dalgalar\' (The Waves) romanını özgün kılan kurgu hangisidir?', 'Altı kişinin iç monologlarının dönüşümlü sunulması', ['Altı kişinin mektuplarının sırayla birbirine gönderilmesi ve cevaplanması biçiminde kurgulanması', 'Tek diyalogdan oluşması', 'Dedektif kurgusu'], 'Roman, altı arkadaşın çocukluktan yaşlılığa iç sesleriyle ilerler ve aralara doğa betimlemeleri girer.'),
  ('Pinter\'ın \'Bekçi\' (The Caretaker) oyununda iki kardeşin evine alınan serserinin yazgısı nasıl biter?', 'Evde kalma umudu boşa çıkar, dışarıda kalır', ['Servet sahibi olur', 'Kardeşlerin evinde kalıcı bir iş bulur', 'Evi satın alır'], 'Davies, kardeşleri birbirine karşı kullanmaya çalışırken ikisinin güvenini de yitirir; oyun güç ve aidiyet mücadelesini işler.'),
  ('Marivaux\'nun \'Aşkın ve Rastlantının Oyunu\'ndaki ana kurgu hangisidir?', 'İki genç, evlenecekleri kişiyi tanımak için uşaklarıyla rol değiştirir', ['İki rakip kralın uşakları, efendilerinin savaşını bitirmek için kıyafet değiştirir', 'Gizli bir hazine arayışı', 'Bir cinayet soruşturması'], 'Silvia ile Dorante, aynı oyunu düşündüğünü bilmeden rol değiştirir; uşakları da efendilerin yerine geçer.'),
];
